/*
 * PURPOSE: Manages OMP CLI process lifecycle and JSON event streaming.
 * Spawns `omp --mode=json -p` for each message, reads JSON events line-by-line,
 * and yields them as an async generator for the WebSocket handler to forward.
 *
 * KEY DECISIONS:
 * - Uses `-p` (print mode) per message: each message is a new process,
 *   but `--resume <sessionId>` maintains conversation context via OMP's JSONL files.
 * - `--mode=json` gives structured events: session, agent_start, turn_start,
 *   message_start, message_update (streaming deltas), message_end, turn_end, agent_end.
 * - `--auto-approve` by default so remote sessions don't hang on tool approval prompts.
 *
 * GOTCHAS:
 * - OMP outputs JSON to stdout, one object per line. stderr may contain warnings.
 * - The `session` event (first after start) contains the session ID — we extract it
 *   so subsequent messages can use `--resume <id>`.
 * - Process must be killable for cancel functionality; we track the PID.
 */

import type { OmpEvent, OmpSessionEvent } from "./types.ts";

export interface OmpSpawnOptions {
  content: string;
  sessionId?: string | null;
  model?: string;
  thinking?: string;
  autoApprove?: boolean;
  cwd?: string;
  tools?: boolean; // enable/disable tools (default: enabled)
}

export interface OmpProcessHandle {
  pid: number;
  sessionId: string | null;
  kill: () => void;
  done: Promise<void>;
}

const OMP_BIN = "omp";

/**
 * Build the OMP CLI argument list from spawn options.
 */
function buildArgs(opts: OmpSpawnOptions): string[] {
  const args: string[] = ["--mode=json", "-p"];

  if (opts.sessionId) {
    args.push("--resume", opts.sessionId);
  }

  if (opts.autoApprove !== false) {
    args.push("--auto-approve");
  }

  if (opts.model) {
    args.push("--model", opts.model);
  }

  if (opts.thinking) {
    args.push("--thinking", opts.thinking);
  }

  if (opts.cwd) {
    args.push("--cwd", opts.cwd);
  }

  // The message content as the positional argument
  args.push(opts.content);

  return args;
}

/**
 * Spawn an OMP process and stream JSON events from stdout.
 * Returns an async generator yielding parsed OmpEvent objects.
 * Also returns a kill function for cancellation.
 */
export function spawnOmp(
  opts: OmpSpawnOptions,
  onSessionId?: (id: string) => void,
): {
  events: AsyncGenerator<OmpEvent, void, void>;
  kill: () => void;
  done: Promise<number | null>;
} {
  const args = buildArgs(opts);
  const cwd = opts.cwd || process.cwd();

  const proc = Bun.spawn([OMP_BIN, ...args], {
    stdout: "pipe",
    stderr: "pipe",
    cwd,
  });

  let killed = false;

  const kill = () => {
    if (!killed) {
      killed = true;
      try {
        proc.kill();
      } catch {
        // Process may have already exited
      }
    }
  };

  const done = proc.exited;

  // Async generator that reads stdout line-by-line and yields parsed events
  async function* events(): AsyncGenerator<OmpEvent, void, void> {
    const reader = proc.stdout.getReader();
    const decoder = new TextDecoder();
    let buffer = "";

    try {
      while (true) {
        const { done: readerDone, value } = await reader.read();
        if (readerDone) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        // Keep the last (possibly incomplete) line in the buffer
        buffer = lines.pop() || "";

        for (const line of lines) {
          const trimmed = line.trim();
          if (!trimmed) continue;

          try {
            const event = JSON.parse(trimmed) as OmpEvent;

            // Extract session ID from the first `session` event
            if (event.type === "session") {
              const sessionEvent = event as OmpSessionEvent;
              onSessionId?.(sessionEvent.id);
            }

            yield event;
          } catch {
            // Not valid JSON — could be a log line or partial output.
            // Yield it as a custom event so the client can see it.
            yield {
              type: "custom",
              customType: "raw_output",
              content: trimmed,
            } satisfies OmpEvent;
          }
        }
      }

      // Process any remaining data in the buffer
      const remaining = buffer.trim();
      if (remaining) {
        try {
          const event = JSON.parse(remaining) as OmpEvent;
          if (event.type === "session") {
            const sessionEvent = event as OmpSessionEvent;
            onSessionId?.(sessionEvent.id);
          }
          yield event;
        } catch {
          yield { type: "custom", customType: "raw_output", content: remaining } satisfies OmpEvent;
        }
      }
    } finally {
      reader.releaseLock();
    }
  }

  return { events: events(), kill, done };
}

/**
 * Get the OMP version string.
 */
export async function getOmpVersion(): Promise<string> {
  try {
    const proc = Bun.spawn([OMP_BIN, "--version"], {
      stdout: "pipe",
      stderr: "pipe",
    });
    const output = await new Response(proc.stdout).text();
    const match = output.match(/omp\/([\d.]+)/);
    return match ? `omp/${match[1]}` : output.trim();
  } catch {
    return "unknown";
  }
}

