/*
 * PURPOSE: Manages a Cloudflare quick tunnel to expose the bridge server
 * for remote access when the phone is not on local WiFi.
 *
 * KEY DECISIONS:
 * - Uses `cloudflared tunnel --url http://localhost:PORT` for a quick tunnel.
 * - Quick tunnels give a random trycloudflare.com URL — no account needed.
 * - The URL is parsed from cloudflared's stderr output.
 *
 * GOTCHAS:
 * - cloudflared prints the URL to stderr, not stdout.
 * - The URL line looks like: "Your quick Tunnel has been created! Visit it at: https://xxx.trycloudflare.com"
 * - The process must stay alive for the tunnel to work; we track it for cleanup.
 */

import type { Subprocess } from "bun";

export type TunnelStatus = "stopped" | "starting" | "active" | "error";

export interface TunnelState {
  url: string | null;
  status: TunnelStatus;
}

let tunnelProc: Subprocess<"pipe", "pipe", "pipe"> | null = null;
let currentUrl: string | null = null;
let currentStatus: TunnelStatus = "stopped";

/**
 * Start a Cloudflare quick tunnel to the given localhost port.
 * Returns when the tunnel URL is detected or timeout is reached.
 */
export async function startTunnel(port: number): Promise<TunnelState> {
  // Kill existing tunnel if any
  stopTunnel();

  currentStatus = "starting";
  currentUrl = null;

  tunnelProc = Bun.spawn(
    ["cloudflared", "tunnel", "--url", `http://localhost:${port}`],
    {
      stdout: "pipe",
      stderr: "pipe",
    },
  );

  // Read stderr to find the tunnel URL
  const reader = tunnelProc.stderr.getReader();
  const decoder = new TextDecoder();
  let buffer = "";

  // Wait up to 15 seconds for the URL to appear
  const timeout = Date.now() + 15000;

  while (Date.now() < timeout) {
    const { done, value } = await reader.read();
    if (done) break;

    buffer += decoder.decode(value, { stream: true });
    const lines = buffer.split("\n");
    buffer = lines.pop() || "";

    for (const line of lines) {
    // Match the tunnel URL from cloudflared output
    const urlMatch = line.match(/https:\/\/[a-z0-9-]+\.trycloudflare\.com/i);
      if (urlMatch) {
        currentUrl = urlMatch[0];
        currentStatus = "active";
        reader.releaseLock();
        return { url: currentUrl, status: "active" };
      }
    }
  }

  reader.releaseLock();
  currentStatus = "error";
  return { url: null, status: "error" };
}

/**
 * Stop the Cloudflare tunnel.
 */
export function stopTunnel(): TunnelState {
  if (tunnelProc) {
    try {
      tunnelProc.kill();
    } catch {
      // Process may have already exited
    }
    tunnelProc = null;
  }
  currentUrl = null;
  currentStatus = "stopped";
  return { url: null, status: "stopped" };
}

/**
 * Get the current tunnel state.
 */
export function getTunnelState(): TunnelState {
  return { url: currentUrl, status: currentStatus };
}

/*
 * PURPOSE: Main bridge server entry point. Combines WebSocket (for real-time
 * OMP event streaming) and REST API (for session listing and status) into a
 * single Bun.serve instance. Also manages the Cloudflare tunnel for remote access.
 *
 * KEY DECISIONS:
 * - Single port (default 9090) serves both HTTP REST and WebSocket.
 * - Token-based auth: a random token is generated on startup and printed to console.
 *   Clients send it via the `Authorization` header or `?token=` query param.
 * - Each WebSocket connection can manage one active OMP process at a time.
 * - OMP is spawned with `--mode=json -p` per message; events are forwarded as-is.
 *
 * ARCHITECTURE:
 *   Mobile App ←→ WebSocket ←→ Bridge Server ←→ OMP CLI (stdin/stdout JSON)
 *                                       ↕
 *                              Cloudflare Tunnel → Internet
 */

import { spawnOmp, getOmpVersion } from "./omp.ts";
import { listSessions, getSessionHistory } from "./sessions.ts";
import { startTunnel, stopTunnel, getTunnelState } from "./tunnel.ts";
import type {
  WsClientCommand,
  WsServerMessage,
  OmpEvent,
  ServerStatus,
  SessionSummary,
} from "./types.ts";

const PORT = parseInt(process.env.OMP_BRIDGE_PORT || "9090", 10);
const AUTH_TOKEN = process.env.OMP_BRIDGE_TOKEN || crypto.randomUUID();

// Track active OMP processes per WebSocket connection
interface ConnectionState {
  ompKill: (() => void) | null;
  ompDone: Promise<number | null> | null;
  currentSessionId: string | null;
}

const connections = new Map<WebSocket, ConnectionState>();
const startTime = Date.now();

/**
 * Validate the auth token from an HTTP request or WebSocket upgrade.
 */
function checkAuth(req: Request): boolean {
  const authHeader = req.headers.get("Authorization");
  if (authHeader === `Bearer ${AUTH_TOKEN}`) return true;

  const url = new URL(req.url);
  const tokenParam = url.searchParams.get("token");
  return tokenParam === AUTH_TOKEN;
}

/**
 * Build the server status response.
 */
async function buildStatus(): Promise<ServerStatus> {
  const ompVersion = await getOmpVersion();
  const tunnel = getTunnelState();
  const sessions = await listSessions();

  return {
    ompVersion,
    uptime: Math.floor((Date.now() - startTime) / 1000),
    tunnelUrl: tunnel.url,
    tunnelStatus: tunnel.status,
    activeSessions: connections.size,
    totalSessions: sessions.length,
    models: [], // Populated from config if needed
  };
}

/**
 * Send a JSON message to a WebSocket client.
 */
function sendWs(ws: WebSocket, msg: WsServerMessage): void {
  ws.send(JSON.stringify(msg));
}

/**
 * Handle an OMP message send command — spawn OMP and stream events to the client.
 */
async function handleSend(
  ws: WebSocket,
  state: ConnectionState,
  cmd: { content: string; sessionId?: string | null; model?: string; thinking?: string; autoApprove?: boolean; cwd?: string },
): Promise<void> {
  // Kill any existing OMP process for this connection
  if (state.ompKill) {
    state.ompKill();
  }

  let resolvedSessionId = cmd.sessionId || null;

  const { events, kill, done } = spawnOmp(
    {
      content: cmd.content,
      sessionId: cmd.sessionId || undefined,
      model: cmd.model,
      thinking: cmd.thinking,
      autoApprove: cmd.autoApprove,
      cwd: cmd.cwd,
    },
    (id) => {
      // Callback when OMP reports the session ID
      resolvedSessionId = id;
      state.currentSessionId = id;
    },
  );

  state.ompKill = kill;
  state.ompDone = done;

  // Stream events to the client
  try {
    for await (const event of events) {
      // Check if WebSocket is still open
      if (ws.readyState !== ws.OPEN) break;

      sendWs(ws, {
        type: "event",
        sessionId: resolvedSessionId || "",
        event,
      });
    }

    // Wait for process to complete
    await done;

    // Signal completion
    sendWs(ws, {
      type: "complete",
      sessionId: resolvedSessionId || "",
    });
  } catch (err) {
    sendWs(ws, {
      type: "error",
      message: `OMP process error: ${err instanceof Error ? err.message : String(err)}`,
      sessionId: resolvedSessionId || undefined,
    });
  } finally {
    state.ompKill = null;
    state.ompDone = null;
  }
}

/**
 * Handle a WebSocket client command.
 */
async function handleCommand(ws: WebSocket, state: ConnectionState, cmd: WsClientCommand): Promise<void> {
  switch (cmd.type) {
    case "send": {
      await handleSend(ws, state, cmd);
      break;
    }

    case "cancel": {
      if (state.ompKill) {
        state.ompKill();
        state.ompKill = null;
        sendWs(ws, { type: "error", message: "Cancelled by user" });
      }
      break;
    }

    case "list_sessions": {
      const sessions: SessionSummary[] = await listSessions();
      sendWs(ws, { type: "sessions", sessions });
      break;
    }

    case "get_history": {
      const result = await getSessionHistory(cmd.sessionId);
      if (result) {
        sendWs(ws, {
          type: "history",
          sessionId: cmd.sessionId,
          messages: result.messages,
          title: result.title,
        });
      } else {
        sendWs(ws, {
          type: "error",
          message: `Session not found: ${cmd.sessionId}`,
        });
      }
      break;
    }

    case "get_status": {
      const status = await buildStatus();
      sendWs(ws, { type: "status", status });
      break;
    }

    case "start_tunnel": {
      sendWs(ws, { type: "tunnel", url: null, status: "starting" });
      const tunnelState = await startTunnel(PORT);
      sendWs(ws, { type: "tunnel", url: tunnelState.url, status: tunnelState.status });
      break;
    }

    case "stop_tunnel": {
      const tunnelState = stopTunnel();
      sendWs(ws, { type: "tunnel", url: tunnelState.url, status: tunnelState.status });
      break;
    }

    default: {
      sendWs(ws, { type: "error", message: `Unknown command type: ${(cmd as { type: string }).type}` });
    }
  }
}

// ─── HTTP REST API ────────────────────────────────────────────────────────────

function handleRest(req: Request): Response {
  const url = new URL(req.url);

  // Auth check
  if (!checkAuth(req)) {
    return new Response(JSON.stringify({ error: "Unauthorized" }), {
      status: 401,
      headers: { "Content-Type": "application/json" },
    });
  }

  // GET /api/status
  if (url.pathname === "/api/status" && req.method === "GET") {
    return buildStatus().then(
      (status) =>
        new Response(JSON.stringify(status), {
          headers: { "Content-Type": "application/json" },
        }),
    );
  }

  // GET /api/sessions
  if (url.pathname === "/api/sessions" && req.method === "GET") {
    return listSessions().then(
      (sessions) =>
        new Response(JSON.stringify(sessions), {
          headers: { "Content-Type": "application/json" },
        }),
    );
  }

  // GET /api/sessions/:id
  const sessionMatch = url.pathname.match(/^\/api\/sessions\/([0-9a-f-]+)$/);
  if (sessionMatch && req.method === "GET") {
    return getSessionHistory(sessionMatch[1]).then((result) => {
      if (!result) {
        return new Response(JSON.stringify({ error: "Session not found" }), {
          status: 404,
          headers: { "Content-Type": "application/json" },
        });
      }
      return new Response(JSON.stringify(result), {
        headers: { "Content-Type": "application/json" },
      });
    });
  }

  // POST /api/tunnel/start
  if (url.pathname === "/api/tunnel/start" && req.method === "POST") {
    return startTunnel(PORT).then(
      (state) =>
        new Response(JSON.stringify(state), {
          headers: { "Content-Type": "application/json" },
        }),
    );
  }

  // POST /api/tunnel/stop
  if (url.pathname === "/api/tunnel/stop" && req.method === "POST") {
    const state = stopTunnel();
    return new Response(JSON.stringify(state), {
      headers: { "Content-Type": "application/json" },
    });
  }

  // GET /api/auth/token — returns the auth token (for development convenience)
  if (url.pathname === "/api/auth/token" && req.method === "GET") {
    return new Response(JSON.stringify({ token: AUTH_TOKEN }), {
      headers: { "Content-Type": "application/json" },
    });
  }

  return new Response(JSON.stringify({ error: "Not found" }), {
    status: 404,
    headers: { "Content-Type": "application/json" },
  });
}

// ─── Server ───────────────────────────────────────────────────────────────────

const server = Bun.serve({
  port: PORT,

  websocket: {
    open(ws: WebSocket) {
      connections.set(ws, {
        ompKill: null,
        ompDone: null,
        currentSessionId: null,
      });
      console.log(`[ws] client connected (${connections.size} total)`);
    },

    async message(ws: WebSocket, message: string | Buffer) {
      const state = connections.get(ws);
      if (!state) return;

      let cmd: WsClientCommand;
      try {
        cmd = JSON.parse(typeof message === "string" ? message : message.toString()) as WsClientCommand;
      } catch {
        sendWs(ws, { type: "error", message: "Invalid JSON command" });
        return;
      }

      await handleCommand(ws, state, cmd);
    },

    close(ws: WebSocket) {
      const state = connections.get(ws);
      if (state?.ompKill) {
        state.ompKill();
      }
      connections.delete(ws);
      console.log(`[ws] client disconnected (${connections.size} total)`);
    },
  },

  fetch(req: Request, server): Response {
    const url = new URL(req.url);

    // WebSocket upgrade
    if (req.headers.get("Upgrade") === "websocket") {
      // Check auth for WebSocket too
      if (!checkAuth(req)) {
        return new Response("Unauthorized", { status: 401 });
      }

      const success = server.upgrade(req);
      if (success) {
        return; // upgrade handled
      }
      return new Response("WebSocket upgrade failed", { status: 400 });
    }

    // CORS headers for REST API
    const response = handleRest(req);
    response.headers.set("Access-Control-Allow-Origin", "*");
    response.headers.set("Access-Control-Allow-Methods", "GET, POST, OPTIONS");
    response.headers.set("Access-Control-Allow-Headers", "Authorization, Content-Type");

    return response;
  },
});

