cd D:/omp-mobile/server && TOKEN=$(psmux capture-pane -t omp-server -p 2>/dev/null | grep "Full auth token:" | sed 's/.*token: //') && cat > test-ws3.ts << 'EOF'
const TOKEN = process.argv[2];
const ws = new WebSocket(`ws://localhost:9090/?token=${TOKEN}`);
let msgCount = 0;
ws.addEventListener("open", () => {
  console.log("[test] connected");
  ws.send(JSON.stringify({ type: "send", content: "say just the word OK, nothing else", thinking: "off", autoApprove: true }));
});
ws.addEventListener("message", (event) => {
  msgCount++;
  const msg = JSON.parse(event.data as string);
  if (msg.type === "event") {
    console.log(`[test] #${msgCount} event: ${msg.event.type}`);
    if (msg.event.type === "message_update" && msg.event.assistantMessageEvent?.delta) {
      process.stdout.write(msg.event.assistantMessageEvent.delta);
    }
    if (msg.event.type === "message_end" && msg.event.message?.usage) {
      console.log(`  usage: in=${msg.event.message.usage.input} out=${msg.event.message.usage.output}`);
    }
  } else if (msg.type === "complete") {
    console.log(`[test] complete: ${msg.sessionId} (${msgCount} msgs total)`);
    ws.close();
  } else if (msg.type === "error") {
    console.error(`[test] error: ${msg.message}`);
    ws.close();
  }
});
ws.addEventListener("close", () => { console.log("[test] closed"); process.exit(0); });
ws.addEventListener("error", (e) => console.error("[test] ws error", e));
setTimeout(() => { console.error("[test] timeout"); process.exit(1); }, 45000);
EOF
bun run test-ws3.ts "$TOKEN" 2>&1

