/*
 * PURPOSE: Manages OMP CLI process lifecycle and JSON event streaming.
 * Spawns `omp --mode=json -p` for each message, reads JSON events line-by-line
 * from stdout via node:readline, and forwards them via a callback.
 *
 * KEY DECISIONS:
 * - Uses node:child_process + readline for reliable line-by-line stdout reading
 * - Message content is piped via stdin (not positional arg) for reliable delivery
 * - `--no-extensions` prevents the omp-modes extension from intercepting --mode=json
 * - `-p` (print mode) per message: each message is a new process,
 *   but `--resume <sessionId>` maintains conversation context via OMP's JSONL files
 * - `--auto-approve` by default so remote sessions don't hang on tool prompts
 *
 * GOTCHAS:
 * - omp-modes extension hijacks --mode flag; must use --no-extensions
 * - OMP reads from stdin in -p mode when no positional arg is given
 * - The `session` event (first line) contains the session ID for --resume
 */

import { spawn } from "node:child_process";
import { createInterface } from "node:readline";
import type { OmpEvent, OmpSessionEvent } from "./types.ts";

export interface OmpSpawnOptions {
  content: string;
  sessionId?: string | null;
  model?: string;
  thinking?: string;
  autoApprove?: boolean;
  cwd?: string;
}

function buildArgs(opts: OmpSpawnOptions): string[] {
  const args: string[] = ["--mode=json", "-p", "--no-extensions"];

  if (opts.sessionId) {
    args.push("--resume", opts.sessionId);
  }
  if (opts.autoApprove !== false) {
    args.push("--auto-approve");
  }
  if (opts.model) {
    args.push("--model", opts.model);
  }
  if (opts.thinking) {
    args.push("--thinking", opts.thinking);
  }
  if (opts.cwd) {
    args.push("--cwd", opts.cwd);
  }

  return args;
}

export interface OmpProcessHandle {
  kill: () => void;
  done: Promise<number | null>;
}

/**
 * Spawn an OMP process and stream JSON events from stdout via callbacks.
 * The message content is written to stdin; OMP reads it in -p mode.
 * onEvent is called for each parsed JSON line from OMP stdout.
 * onSessionId is called when the `session` event is received (first line).
 */
export function spawnOmp(
  opts: OmpSpawnOptions,
  onEvent: (event: OmpEvent) => void,
  onSessionId: (id: string) => void,
): OmpProcessHandle {
  const args = buildArgs(opts);
  const cwd = opts.cwd || process.cwd();

  const child = spawn("omp", args, {
    stdio: ["pipe", "pipe", "pipe"],
    cwd,
    shell: false,
  });

  // Write the message content to stdin and close it
  child.stdin.write(opts.content);
  child.stdin.end();

  const rl = createInterface({ input: child.stdout });

  rl.on("line", (line: string) => {
    const trimmed = line.trim();
    if (!trimmed) return;

    try {
      const event = JSON.parse(trimmed) as OmpEvent;
      if (event.type === "session") {
        const sessionEvent = event as OmpSessionEvent;
        onSessionId(sessionEvent.id);
      }
      onEvent(event);
    } catch {
      onEvent({ type: "custom", customType: "raw_output", content: trimmed } satisfies OmpEvent);
    }
  });

  // Log stderr for debugging
  const stderrRL = createInterface({ input: child.stderr });
  stderrRL.on("line", (line: string) => {
    console.error(`[omp:stderr] ${line}`);
  });

  const done = new Promise<number | null>((resolve) => {
    child.on("close", (code) => resolve(code));
    child.on("error", (err) => {
      console.error(`[omp:error] ${err.message}`);
      resolve(null);
    });
  });

  return {
    kill: () => {
      try {
        child.kill();
      } catch {
        // Process may have already exited
      }
    },
    done,
  };
}

/**
 * Get the OMP version string.
 */
export async function getOmpVersion(): Promise<string> {
  try {
    const proc = Bun.spawn(["omp", "--version"], {
      stdout: "pipe",
      stderr: "pipe",
    });
    const output = await new Response(proc.stdout).text();
    const match = output.match(/omp\/([\d.]+)/);
    return match ? `omp/${match[1]}` : output.trim();
  } catch {
    return "unknown";
  }
}

