/*
 * PURPOSE: Manages OMP CLI process lifecycle and JSON event streaming.
 * Spawns `omp --mode=json -p` for each message, reads JSON events from stdout,
 * and forwards them via a callback. The done promise resolves only after
 * stdout's 'end' event, guaranteeing all events have been forwarded before
 * the caller sends its 'complete' message.
 *
 * KEY DECISIONS:
 * - Raw `data` events on child.stdout instead of readline — readline's close
 *   event ordering was unreliable in Bun; raw data gives us full control.
 * - `done` resolves on `child.stdout.on("end")`, which fires after all data
 *   has been consumed but before the child's `close` event.
 * - `--no-extensions` prevents omp-modes from intercepting --mode=json.
 * - Message content piped via stdin for reliable delivery.
 *
 * GOTCHAS:
 * - omp-modes extension hijacks --mode flag; must use --no-extensions
 * - OMP reads from stdin in -p mode when no positional arg is given
 * - The `session` event (first line) contains the session ID for --resume
 */

import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import type { OmpEvent, OmpSessionEvent } from "./types.ts";

export interface OmpSpawnOptions {
  content: string;
  sessionId?: string | null;
  model?: string;
  thinking?: string;
  autoApprove?: boolean;
  cwd?: string;
}

function buildArgs(opts: OmpSpawnOptions): string[] {
  const args: string[] = ["--mode=json", "-p", "--no-extensions"];

  if (opts.sessionId) {
    args.push("--resume", opts.sessionId);
  }
  if (opts.autoApprove !== false) {
    args.push("--auto-approve");
  }
  if (opts.model) {
    args.push("--model", opts.model);
  }
  if (opts.thinking) {
    args.push("--thinking", opts.thinking);
  }
  if (opts.cwd) {
    args.push("--cwd", opts.cwd);
  }

  return args;
}

export interface OmpProcessHandle {
  kill: () => void;
  done: Promise<number | null>;
}

function processLine(
  line: string,
  onEvent: (event: OmpEvent) => void,
  onSessionId: (id: string) => void,
): void {
  const trimmed = line.trim();
  if (!trimmed) return;

  try {
    const event = JSON.parse(trimmed) as OmpEvent;
    if (event.type === "session") {
      onSessionId((event as OmpSessionEvent).id);
    }
    onEvent(event);
  } catch {
    onEvent({ type: "custom", customType: "raw_output", content: trimmed } satisfies OmpEvent);
  }
}

export function spawnOmp(
  opts: OmpSpawnOptions,
  onEvent: (event: OmpEvent) => void,
  onSessionId: (id: string) => void,
): OmpProcessHandle {
  const args = buildArgs(opts);
  const cwd = opts.cwd || process.cwd();

  const child: ChildProcessWithoutNullStreams = spawn("omp", args, {
    stdio: ["pipe", "pipe", "pipe"],
    cwd,
    shell: false,
  });

  // Write message to stdin and close
  child.stdin.write(opts.content);
  child.stdin.end();

  let buffer = "";

  // Process stdout data as it arrives — forward events immediately
  child.stdout.on("data", (chunk: Buffer) => {
    buffer += chunk.toString("utf-8");
    const lines = buffer.split("\n");
    buffer = lines.pop() || "";

    for (const line of lines) {
      processLine(line, onEvent, onSessionId);
    }
  });

  // Log stderr for debugging
  let stderrBuf = "";
  child.stderr.on("data", (chunk: Buffer) => {
    stderrBuf += chunk.toString("utf-8");
    const lines = stderrBuf.split("\n");
    stderrBuf = lines.pop() || "";
    for (const line of lines) {
      console.error(`[omp:stderr] ${line}`);
    }
  });

  // done resolves after stdout ends (all data consumed) — guarantees
  // all events have been forwarded before the caller sends 'complete'.
  const done = new Promise<number | null>((resolve) => {
    child.stdout.on("end", () => {
      // Process any remaining data in the buffer
      if (buffer.trim()) {
        processLine(buffer, onEvent, onSessionId);
        buffer = "";
      }
      // Wait for the process to actually exit to get the exit code
      child.on("close", (code) => resolve(code));
    });

    child.on("error", (err) => {
      console.error(`[omp:error] ${err.message}`);
      resolve(null);
    });
  });

  return {
    kill: () => {
      try {
        child.kill();
      } catch {
        // Process may have already exited
      }
    },
    done,
  };
}

export async function getOmpVersion(): Promise<string> {
  try {
    const proc = Bun.spawn(["omp", "--version"], {
      stdout: "pipe",
      stderr: "pipe",
    });
    const output = await new Response(proc.stdout).text();
    const match = output.match(/omp\/([\d.]+)/);
    return match ? `omp/${match[1]}` : output.trim();
  } catch {
    return "unknown";
  }
}

