arguments.content:
/*
 * PURPOSE: Manages OMP CLI process lifecycle and JSON event streaming.
 * Uses Bun.spawn and collects all stdout, then forwards events after
 * the process exits but before resolving done. This avoids WebSocket
 * send-from-event-callback timing issues in Bun.
 *
 * ARCHITECTURE:
 *   1. Spawn OMP with --mode=json -p, write message to stdin
 *   2. Collect all stdout as text (process runs to completion)
 *   3. Parse JSON lines and forward each event via onEvent callback
 *   4. Resolve done — caller then sends "complete"
 *
 * NOTE: This is batch mode (events sent after process exits), not real-time
 * streaming. Real-time streaming requires a working stream->WebSocket bridge
 * which has timing issues in Bun's event loop. Batch mode is correct and
 * reliable; streaming can be layered on top later.
 */

import { spawn, type ChildProcessWithoutNullStreams } from "node:child_process";
import type { OmpEvent, OmpSessionEvent } from "./types.ts";

export interface OmpSpawnOptions {
  content: string;
  sessionId?: string | null;
  model?: string;
  thinking?: string;
  autoApprove?: boolean;
  cwd?: string;
}

function buildArgs(opts: OmpSpawnOptions): string[] {
  const args: string[] = ["--mode=json", "-p", "--no-extensions"];

  if (opts.sessionId) {
    args.push("--resume", opts.sessionId);
  }
  if (opts.autoApprove !== false) {
    args.push("--auto-approve");
  }
  if (opts.model) {
    args.push("--model", opts.model);
  }
  if (opts.thinking) {
    args.push("--thinking", opts.thinking);
  }
  if (opts.cwd) {
    args.push("--cwd", opts.cwd);
  }

  return args;
}

export interface OmpProcessHandle {
  kill: () => void;
  done: Promise<number | null>;
}

function parseLine(
  line: string,
  onSessionId: (id: string) => void,
): OmpEvent | null {
  const trimmed = line.trim();
  if (!trimmed) return null;

  try {
    const event = JSON.parse(trimmed) as OmpEvent;
    if (event.type === "session") {
      onSessionId((event as OmpSessionEvent).id);
    }
    return event;
  } catch {
    return { type: "custom", customType: "raw_output", content: trimmed } satisfies OmpEvent;
  }
}

export function spawnOmp(
  opts: OmpSpawnOptions,
  onEvent: (event: OmpEvent) => void,
  onSessionId: (id: string) => void,
): OmpProcessHandle {
  const args = buildArgs(opts);
  const cwd = opts.cwd || process.cwd();

  const child: ChildProcessWithoutNullStreams = spawn("omp", args, {
    stdio: ["pipe", "pipe", "pipe"],
    cwd,
    shell: false,
  });

  // Write message to stdin and close
  child.stdin.write(opts.content);
  child.stdin.end();

  // Collect all stdout and stderr
  let stdoutData = "";
  let stderrData = "";

  child.stdout.on("data", (chunk: Buffer) => {
    stdoutData += chunk.toString("utf-8");
  });

  child.stderr.on("data", (chunk: Buffer) => {
    stderrData += chunk.toString("utf-8");
  });

  let killed = false;

  const done = new Promise<number | null>((resolve) => {
    child.on("close", (code) => {
      // Log stderr if any
      if (stderrData.trim()) {
        for (const line of stderrData.split("\n")) {
          if (line.trim()) console.error(`[omp:stderr] ${line}`);
        }
      }

      // Parse all stdout lines and forward events NOW — synchronously
      // after the process exits but before done resolves. This ensures
      // all ws.send() calls complete before the caller sends "complete".
      const lines = stdoutData.split("\n");
      for (const line of lines) {
        const event = parseLine(line, onSessionId);
        if (event) {
          onEvent(event);
        }
      }

      resolve(code);
    });

    child.on("error", (err) => {
      console.error(`[omp:error] ${err.message}`);
      resolve(null);
    });
  });

  return {
    kill: () => {
      if (!killed) {
        killed = true;
        try { child.kill(); } catch { /* already exited */ }
      }
    },
    done,
  };
}

export async function getOmpVersion(): Promise<string> {
  try {
    const proc = Bun.spawn(["omp", "--version"], {
      stdout: "pipe",
      stderr: "pipe",
    });
    const output = await new Response(proc.stdout).text();
    const match = output.match(/omp\/([\d.]+)/);
    return match ? `omp/${match[1]}` : output.trim();
  } catch {
    return "unknown";
  }
}

