      type: "complete",
      sessionId,
    });
    console.log(`[handleSend] sent complete`);
  } catch (err) {
    sendWs(ws, {
      type: "error",
      message: `OMP process error: ${err instanceof Error ? err.message : String(err)}`,
      sessionId: handle.sessionId || cmd.sessionId || undefined,
    });
  } finally {
    state.ompKill = null;
  }
