/*
 * PURPOSE: Mantine-inspired gray dark theme for OMP Mobile.
 * Defines color tokens, spacing scale, typography, and radii.
 * Inspired by Mantine UI's dark palette but with a gray-forward aesthetic
 * similar to Vercel/Linear dark modes.
 *
 * DESIGN PRINCIPLES:
 * - High contrast text on very dark backgrounds for readability
 * - Subtle borders that separate without being noisy
 * - Gray accent color (not blue/purple) per user request
 * - Consistent 4px-based spacing system
 */

// ─── Color Tokens ─────────────────────────────────────────────────────────────

export const colors = {
  // Backgrounds
  bg: "#0B0C0E",           // App background (darkest)
  bgSecondary: "#111316",  // Tab bar, headers
  surface: "#151619",      // Cards, inputs, elevated surfaces
  surfaceHover: "#1C1D21", // Hover states
  surfaceActive: "#232529", // Active/pressed states

  // Borders
  border: "#26282D",
  borderSubtle: "#1E2024",

  // Text
  text: "#E4E6EA",         // Primary text (high contrast)
  textSecondary: "#9BA1AA", // Secondary text
  textMuted: "#61676F",    // Muted/placeholder text
  textWhite: "#FAFAFA",    // Pure white text for emphasis

  // Accent (gray-forward)
  accent: "#8B8D92",       // Primary accent
  accentBright: "#B0B3B8", // Brighter accent for hover/active
  accentDim: "#5C5E63",    // Dimmed accent

  // Semantic
  success: "#4ADE80",
  successDim: "#22C55E33",
  warning: "#FBBF24",
  warningDim: "#FBBF2433",
  error: "#F87171",
  errorDim: "#F8717133",
  info: "#60A5FA",
  infoDim: "#60A5FA33",

  // Role colors (chat avatars)
  user: "#6B7280",         // User messages
  assistant: "#8B8D92",    // Assistant messages
  system: "#61676F",        // System messages

  // Status indicators
  online: "#4ADE80",
  offline: "#61676F",
  connecting: "#FBBF24",
} as const;

// ─── Spacing Scale (4px base) ────────────────────────────────────────────────

export const spacing = {
  xs: 4,
  sm: 8,
  md: 12,
  lg: 16,
  xl: 20,
  xxl: 24,
  xxxl: 32,
} as const;

// ─── Typography ───────────────────────────────────────────────────────────────

export const fontSizes = {
  xs: 11,
  sm: 13,
  md: 14,
  lg: 16,
  xl: 18,
  xxl: 20,
  xxxl: 24,
  title: 28,
} as const;

export const fontWeights = {
  regular: "400" as const,
  medium: "500" as const,
  semibold: "600" as const,
  bold: "700" as const,
} as const;

export const lineHeights = {
  xs: 16,
  sm: 18,
  md: 20,
  lg: 22,
  xl: 26,
  xxl: 30,
  title: 34,
} as const;

// ─── Radii ────────────────────────────────────────────────────────────────────

export const radii = {
  xs: 4,
  sm: 6,
  md: 8,
  lg: 12,
  xl: 16,
  pill: 999,
} as const;

// ─── Type ────────────────────────────────────────────────────────────────────

export type ColorToken = keyof typeof colors;
export type SpacingToken = keyof typeof spacing;
export type FontSizeToken = keyof typeof fontSizes;
export type FontWeightToken = keyof typeof fontWeights;
export type RadiusToken = keyof typeof radii;

/*
 * PURPOSE: Chat message component — renders a single user or assistant message
 * with avatar, text content, thinking blocks, tool calls, and usage info.
 * Following Mantine-inspired spacing and typography.
 */

import React from "react";
import { View, StyleSheet } from "react-native";
import { colors, spacing, fontSizes, fontWeights, lineHeights, radii } from "../../theme";
import { Text } from "../ui/Text";
import { Avatar } from "../ui/Avatar";
import type { OmpMessage, OmpContentBlock } from "../../types";

interface ChatMessageProps {
  message: OmpMessage;
  isStreaming?: boolean;
}

export function ChatMessage({ message, isStreaming }: ChatMessageProps) {
  const isUser = message.role === "user";
  const roleColor = isUser ? colors.user : colors.assistant;

  // Extract text content from content blocks
  const textBlocks = message.content?.filter((c: OmpContentBlock) => c.type === "text") || [];
  const thinkingBlocks = message.content?.filter((c: OmpContentBlock) => c.type === "thinking") || [];
  const toolBlocks = message.content?.filter((c: OmpContentBlock) => c.type === "tool_use") || [];

  return (
    <View style={[styles.container, isUser ? styles.userContainer : styles.assistantContainer]}>
      {!isUser && (
        <Avatar size={32} color={roleColor} label="O" />
      )}

      <View style={[styles.bubble, isUser ? styles.userBubble : styles.assistantBubble]}>
        {/* Thinking blocks (collapsible) */}
        {thinkingBlocks.length > 0 && (
          <View style={styles.thinkingSection}>
            {thinkingBlocks.map((block: OmpContentBlock, i: number) => (
              <ThinkingBlock key={i} text={block.thinking || ""} />
            ))}
          </View>
        )}

        {/* Text content */}
        {textBlocks.map((block: OmpContentBlock, i: number) => (
          <Text
            key={i}
            size="md"
            color={isUser ? "text" : "text"}
            style={styles.textBlock}
          >
            {block.text || ""}
            {isStreaming && i === textBlocks.length - 1 ? "▋" : ""}
          </Text>
        ))}

        {/* Tool calls */}
        {toolBlocks.length > 0 && (
          <View style={styles.toolSection}>
            {toolBlocks.map((block: OmpContentBlock, i: number) => (
              <View key={i} style={styles.toolCall}>
                <Text size="xs" weight="medium" color="textSecondary">
                  🔧 {block.toolName || "tool"}
                </Text>
              </View>
            ))}
          </View>
        )}

        {/* Usage info for assistant messages */}
        {!isUser && message.usage && (
          <View style={styles.usageBar}>
            {message.model && (
              <Text size="xs" color="textMuted">
                {message.model}
              </Text>
            )}
            {message.usage.cost && message.usage.cost.total > 0 && (
              <Text size="xs" color="textMuted">
                ${message.usage.cost.total.toFixed(4)}
              </Text>
            )}
            {message.duration && (
              <Text size="xs" color="textMuted">
                {(message.duration / 1000).toFixed(1)}s
              </Text>
            )}
            {message.usage.output > 0 && (
              <Text size="xs" color="textMuted">
                {message.usage.output} tok
              </Text>
            )}
          </View>
        )}
      </View>

      {isUser && (
        <Avatar size={32} color={colors.user} label="U" />
      )}
    </View>
  );
}

function ThinkingBlock({ text }: { text: string }) {
  const [expanded, setExpanded] = React.useState(false);
  const preview = text.slice(0, 80) + (text.length > 80 ? "..." : "");

  return (
    <Pressable onPress={() => setExpanded(!expanded)} style={styles.thinkingBlock}>
      <View style={styles.thinkingHeader}>
        <Text size="xs" weight="medium" color="textMuted">
          💭 Thinking {expanded ? "▾" : "▸"}
        </Text>
      </View>
      <Text size="xs" color="textMuted" style={styles.thinkingText}>
        {expanded ? text : preview}
      </Text>
    </Pressable>
  );
}

// Need Pressable import
import { Pressable } from "react-native";

const styles = StyleSheet.create({
  container: {
    flexDirection: "row",
    gap: spacing.sm,
    paddingHorizontal: spacing.lg,
    paddingVertical: spacing.sm,
  },
  userContainer: {
    justifyContent: "flex-end",
  },
  assistantContainer: {
    justifyContent: "flex-start",
  },
  bubble: {
    maxWidth: "85%",
    padding: spacing.md,
    borderRadius: radii.lg,
    gap: spacing.xs,
  },
  userBubble: {
    backgroundColor: colors.surfaceActive,
    borderTopRightRadius: radii.xs,
  },
  assistantBubble: {
    backgroundColor: colors.surface,
    borderTopLeftRadius: radii.xs,
  },
  textBlock: {
    lineHeight: lineHeights.md,
  },
  thinkingSection: {
    gap: spacing.xs,
  },
  thinkingBlock: {
    backgroundColor: colors.bgSecondary,
    borderRadius: radii.md,
    padding: spacing.sm,
    borderWidth: 1,
    borderColor: colors.borderSubtle,
  },
  thinkingHeader: {
    marginBottom: spacing.xs,
  },
  thinkingText: {
    lineHeight: lineHeights.sm,
  },
  toolSection: {
    gap: spacing.xs,
    marginTop: spacing.xs,
  },
  toolCall: {
    backgroundColor: colors.bgSecondary,
    borderRadius: radii.sm,
    padding: spacing.sm,
    borderWidth: 1,
    borderColor: colors.borderSubtle,
  },
  usageBar: {
    flexDirection: "row",
    gap: spacing.sm,
    marginTop: spacing.xs,
    paddingTop: spacing.xs,
    borderTopWidth: 1,
    borderTopColor: colors.borderSubtle,
  },
});

