/*
 * PURPOSE: Shared TypeScript types for the OMP Mobile app.
 * Mirrors the server-side types for the WebSocket protocol and OMP events.
 */

export interface OmpContentBlock {
  type: "text" | "thinking" | "tool_use" | "tool_result" | "image";
  text?: string;
  thinking?: string;
  thinkingSignature?: string;
  toolCallId?: string;
  toolName?: string;
  args?: string;
  content?: string;
  image?: string;
}

export interface OmpUsage {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
  totalTokens: number;
  cost: {
    input: number;
    output: number;
    cacheRead: number;
    cacheWrite: number;
    total: number;
  };
}

export interface OmpMessage {
  role: "user" | "assistant" | "system";
  content: OmpContentBlock[];
  attribution?: string;
  timestamp?: number;
  api?: string;
  provider?: string;
  model?: string;
  usage?: OmpUsage;
  stopReason?: string;
  responseId?: string;
  duration?: number;
  ttft?: number;
  completedAt?: number;
}

export type OmpEventType =
  | "session"
  | "agent_start"
  | "turn_start"
  | "message_start"
  | "message_update"
  | "message_end"
  | "turn_end"
  | "agent_end"
  | "custom"
  | "notice";

export interface OmpEvent {
  type: OmpEventType;
  [key: string]: unknown;
}

export interface SessionSummary {
  id: string;
  title: string;
  timestamp: string;
  cwd: string;
  messageCount: number;
  size: number;
}

export interface ServerStatus {
  ompVersion: string;
  uptime: number;
  tunnelUrl: string | null;
  tunnelStatus: "stopped" | "starting" | "active" | "error";
  activeSessions: number;
  totalSessions: number;
  models: string[];
}

export type WsClientCommand =
  | { type: "send"; content: string; sessionId?: string | null; model?: string; thinking?: string; autoApprove?: boolean; cwd?: string }
  | { type: "list_sessions" }
  | { type: "get_history"; sessionId: string }
  | { type: "get_status" }
  | { type: "cancel" }
  | { type: "start_tunnel" }
  | { type: "stop_tunnel" };

export type WsServerMessage =
  | { type: "event"; sessionId: string; event: OmpEvent }
  | { type: "complete"; sessionId: string }
  | { type: "error"; message: string; sessionId?: string }
  | { type: "sessions"; sessions: SessionSummary[] }
  | { type: "history"; sessionId: string; messages: OmpMessage[]; title?: string }
  | { type: "status"; status: ServerStatus }
  | { type: "tunnel"; url: string | null; status: string };

export type WsStatus = "disconnected" | "connecting" | "connected";

/*
 * PURPOSE: Chat screen — full conversation interface with OMP.
 * Shows message history, streaming responses, and input bar.
 */

import React, { useState, useEffect } from "react";
import { View, StyleSheet, KeyboardAvoidingView, Platform } from "react-native";
import { colors, spacing } from "../theme";
import { MessageList } from "../components/chat/MessageList";
import { ChatInput } from "../components/chat/ChatInput";
import { Text } from "../components/ui/Text";
import { useStore } from "../store";

export function ChatScreen({ route }: { route: { params?: { sessionId?: string } } }) {
  const [input, setInput] = useState("");
  const {
    messages,
    streamingText,
    isGenerating,
    currentSessionId,
    sendMessage,
    cancelGeneration,
    loadSession,
    startNewSession,
    wsStatus,
  } = useStore();

  const sessionId = route?.params?.sessionId;

  useEffect(() => {
    if (sessionId) {
      loadSession(sessionId);
    } else {
      startNewSession();
    }
  }, [sessionId]);

  const handleSend = () => {
    if (!input.trim()) return;
    sendMessage(input.trim());
    setInput("");
  };

  if (wsStatus !== "connected") {
    return (
      <View style={styles.disconnected}>
        <Text size="lg" color="textMuted">Not connected to server</Text>
        <Text size="sm" color="textMuted" style={{ marginTop: spacing.xs }}>
          Go to Settings to configure your server connection
        </Text>
      </View>
    );
  }

  return (
    <KeyboardAvoidingView
      style={styles.container}
      behavior={Platform.OS === "ios" ? "padding" : undefined}
    >
      <View style={styles.header}>
        <Text size="sm" color="textMuted" weight="medium">
          {currentSessionId ? "Session" : "New conversation"}
        </Text>
      </View>

      <View style={styles.messagesContainer}>
        <MessageList
          messages={messages}
          streamingText={streamingText}
          isGenerating={isGenerating}
        />
      </View>

      <ChatInput
        value={input}
        onChangeText={setInput}
        onSend={handleSend}
        onCancel={cancelGeneration}
        isGenerating={isGenerating}
        placeholder={isGenerating ? "Generating..." : "Send a message..."}
      />
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: colors.bg,
  },
  header: {
    paddingHorizontal: spacing.lg,
    paddingVertical: spacing.sm,
    borderBottomWidth: 1,
    borderBottomColor: colors.border,
    backgroundColor: colors.bgSecondary,
  },
  messagesContainer: {
    flex: 1,
  },
  disconnected: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: colors.bg,
  },
});

