/*
 * PURPOSE: Chat screen — full conversation interface with OMP.
 * Shows message history, streaming responses, reasoning, tool calls,
 * model selector, thinking level selector, and input bar.
 */

import React, { useState, useEffect, useRef } from "react";
import { View, StyleSheet, KeyboardAvoidingView, Platform, ScrollView, Pressable } from "react-native";
import { colors, spacing, fontSizes, radii } from "../theme";
import { MessageList } from "../components/chat/MessageList";
import { ChatInput } from "../components/chat/ChatInput";
import { Text } from "../components/ui/Text";
import { useStore } from "../store";
import { MODEL_PRESETS, THINKING_LEVELS } from "../types";
import type { ThinkingLevel } from "../types";

export function ChatScreen({ route }: { route: { params?: { sessionId?: string } } }) {
  const [input, setInput] = useState("");
  const [showModelPicker, setShowModelPicker] = useState(false);
  const {
    messages,
    streamingText,
    streamingThinking,
    isGenerating,
    currentSessionId,
    selectedModel,
    thinkingLevel,
    toolCalls,
    notices,
    sessionTitle,
    sendMessage,
    cancelGeneration,
    loadSession,
    startNewSession,
    setSelectedModel,
    setThinkingLevel,
    wsStatus,
  } = useStore();

  const sessionId = route?.params?.sessionId;

  useEffect(() => {
    if (sessionId) {
      loadSession(sessionId);
    } else {
      startNewSession();
    }
  }, [sessionId]);

  const handleSend = () => {
    if (!input.trim()) return;
    sendMessage(input.trim());
    setInput("");
  };

  if (wsStatus !== "connected") {
    return (
      <View style={styles.disconnected}>
        <Text size="lg" color="textMuted">Not connected to server</Text>
        <Text size="sm" color="textMuted" style={{ marginTop: spacing.xs }}>
          Go to Settings to configure your server connection
        </Text>
      </View>
    );
  }

  const modelLabel = MODEL_PRESETS.find((m) => m.value === selectedModel)?.label || selectedModel || "Default";

  return (
    <KeyboardAvoidingView
      style={styles.container}
      behavior={Platform.OS === "ios" ? "padding" : undefined}
    >
      {/* Header with model + thinking level */}
      <View style={styles.header}>
        <Pressable style={styles.modelBadge} onPress={() => setShowModelPicker(!showModelPicker)}>
          <Text size="xs" weight="medium" color="accent">{modelLabel}</Text>
          <Text size="xs" color="textMuted">{"  think:" + thinkingLevel}</Text>
        </Pressable>
        {sessionTitle && (
          <Text size="xs" color="textMuted" numberOfLines={1} style={styles.title}>{sessionTitle}</Text>
        )}
      </View>

      {/* Model picker dropdown */}
      {showModelPicker && (
        <View style={styles.modelPicker}>
          <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.modelScroll}>
            {MODEL_PRESETS.map((m) => (
              <Pressable
                key={m.value}
                style={[styles.modelOption, selectedModel === m.value && styles.modelOptionActive]}
                onPress={() => { setSelectedModel(m.value); setShowModelPicker(false); }}
              >
                <Text size="xs" weight="medium" color={selectedModel === m.value ? "text" : "textSecondary"}>
                  {m.label}
                </Text>
              </Pressable>
            ))}
          </ScrollView>
          <View style={styles.thinkingRow}>
            <Text size="xs" color="textMuted">Thinking:</Text>
            <ScrollView horizontal showsHorizontalScrollIndicator={false}>
              {THINKING_LEVELS.map((lvl) => (
                <Pressable
                  key={lvl}
                  style={[styles.thinkingOption, thinkingLevel === lvl && styles.thinkingOptionActive]}
                  onPress={() => setThinkingLevel(lvl as ThinkingLevel)}
                >
                  <Text size="xs" weight="medium" color={thinkingLevel === lvl ? "text" : "textSecondary"}>
                    {lvl}
                  </Text>
                </Pressable>
              ))}
            </ScrollView>
          </View>
        </View>
      )}

      {/* Messages */}
      <View style={styles.messagesContainer}>
        <MessageList
          messages={messages}
          streamingText={streamingText}
          streamingThinking={streamingThinking}
          isGenerating={isGenerating}
          toolCalls={toolCalls}
          notices={notices}
        />
      </View>

      {/* Input */}
      <ChatInput
        value={input}
        onChangeText={setInput}
        onSend={handleSend}
        onCancel={cancelGeneration}
        isGenerating={isGenerating}
        placeholder={isGenerating ? "Generating..." : "Send a message..."}
      />
    </KeyboardAvoidingView>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: colors.bg },
  header: {
    flexDirection: "row",
    alignItems: "center",
    gap: spacing.sm,
    paddingHorizontal: spacing.lg,
    paddingVertical: spacing.sm,
    borderBottomWidth: 1,
    borderBottomColor: colors.border,
    backgroundColor: colors.bgSecondary,
  },
  modelBadge: {
    flexDirection: "row",
    alignItems: "center",
    backgroundColor: colors.surface,
    borderRadius: radii.sm,
    paddingHorizontal: spacing.sm,
    paddingVertical: spacing.xs,
    borderWidth: 1,
    borderColor: colors.border,
  },
  title: { flex: 1, textAlign: "right" },
  modelPicker: {
    backgroundColor: colors.bgSecondary,
    borderBottomWidth: 1,
    borderBottomColor: colors.border,
    paddingVertical: spacing.sm,
  },
  modelScroll: { paddingHorizontal: spacing.lg, gap: spacing.xs },
  modelOption: {
    backgroundColor: colors.surface,
    borderRadius: radii.sm,
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.xs,
    marginRight: spacing.xs,
    borderWidth: 1,
    borderColor: colors.border,
  },
  modelOptionActive: {
    backgroundColor: colors.accent,
    borderColor: colors.accent,
  },
  thinkingRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: spacing.sm,
    paddingHorizontal: spacing.lg,
    marginTop: spacing.sm,
  },
  thinkingOption: {
    backgroundColor: colors.surface,
    borderRadius: radii.xs,
    paddingHorizontal: spacing.sm,
    paddingVertical: 2,
    marginRight: spacing.xs,
    borderWidth: 1,
    borderColor: colors.border,
  },
  thinkingOptionActive: {
    backgroundColor: colors.accent,
    borderColor: colors.accent,
  },
  messagesContainer: { flex: 1 },
  disconnected: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: colors.bg,
  },
});

/*
 * PURPOSE: Scrollable message list for the chat screen.
 * Auto-scrolls to bottom. Shows streaming text, thinking, tool calls, notices.
 */

import React, { useRef, useEffect } from "react";
import { FlatList, View, StyleSheet } from "react-native";
import { colors, spacing, radii } from "../../theme";
import { ChatMessage } from "./ChatMessage";
import { Text } from "../ui/Text";
import type { OmpMessage, ToolCallInfo } from "../../types";

interface MessageListProps {
  messages: OmpMessage[];
  streamingText?: string;
  streamingThinking?: string;
  isGenerating?: boolean;
  toolCalls?: ToolCallInfo[];
  notices?: { level: string; message: string }[];
}

export function MessageList({ messages, streamingText, streamingThinking, isGenerating, toolCalls, notices }: MessageListProps) {
  const listRef = useRef<FlatList>(null);

  useEffect(() => {
    if (messages.length > 0 || streamingText || streamingThinking) {
      setTimeout(() => listRef.current?.scrollToEnd({ animated: true }), 50);
    }
  }, [messages.length, streamingText, streamingThinking, toolCalls?.length, notices?.length]);

  const displayMessages: OmpMessage[] = [...messages];

  // Build a streaming assistant message if we have any streaming content
  if (isGenerating && (streamingText || streamingThinking)) {
    const content: { type: string; text?: string; thinking?: string }[] = [];
    if (streamingThinking) content.push({ type: "thinking", thinking: streamingThinking });
    if (streamingText) content.push({ type: "text", text: streamingText });
    displayMessages.push({ role: "assistant", content: content as never });
  }

  if (displayMessages.length === 0 && !isGenerating) {
    return (
      <View style={styles.empty}>
        <Text size="lg" color="textMuted">No messages yet</Text>
        <Text size="sm" color="textMuted" style={{ marginTop: spacing.xs }}>
          Send a message to start the conversation
        </Text>
      </View>
    );
  }

  return (
    <FlatList
      ref={listRef}
      data={displayMessages}
      keyExtractor={(_, index) => String(index)}
      renderItem={({ item, index }) => (
        <ChatMessage
          message={item}
          isStreaming={isGenerating && index === displayMessages.length - 1}
        />
      )}
      contentContainerStyle={styles.list}
      onContentSizeChange={() => listRef.current?.scrollToEnd({ animated: false })}
      showsVerticalScrollIndicator={false}
      ListFooterComponent={
        isGenerating ? (
          <View>
            {/* Active tool calls */}
            {toolCalls && toolCalls.length > 0 && (
              <View style={styles.toolCallsContainer}>
                {toolCalls.map((tc) => (
                  <ToolCallView key={tc.id} tc={tc} />
                ))}
              </View>
            )}
            {/* Notices */}
            {notices && notices.length > 0 && (
              <View style={styles.noticesContainer}>
                {notices.map((n, i) => (
                  <View key={i} style={styles.notice}>
                    <Text size="xs" color={n.level === "warning" ? "warning" : "textMuted"}>
                      {n.message}
                    </Text>
                  </View>
                ))}
              </View>
            )}
            {/* Generating indicator */}
            <View style={styles.generatingIndicator}>
              <Text size="xs" color="textMuted">{"● ● ●"}</Text>
            </View>
          </View>
        ) : null
      }
    />
  );
}

function ToolCallView({ tc }: { tc: ToolCallInfo }) {
  const [expanded, setExpanded] = React.useState(false);
  const statusIcon = tc.status === "running" ? "○" : tc.status === "done" ? "●" : "✕";
  const statusColor = tc.status === "running" ? "warning" : tc.status === "done" ? "success" : "error";

  return (
    <Pressable onPress={() => setExpanded(!expanded)} style={styles.toolCall}>
      <View style={styles.toolCallHeader}>
        <Text size="xs" weight="medium" color={statusColor as "success" | "warning" | "error"}>
          {statusIcon + " " + tc.name}
        </Text>
        <Text size="xs" color="textMuted">{expanded ? "▾" : "▸"}</Text>
      </View>
      {expanded && tc.args && (
        <Text size="xs" color="textMuted" style={styles.toolCallArgs}>
          {tc.args.length > 200 ? tc.args.slice(0, 200) + "..." : tc.args}
        </Text>
      )}
    </Pressable>
  );
}

import { Pressable } from "react-native";

const styles = StyleSheet.create({
  list: { paddingVertical: spacing.md },
  empty: { flex: 1, alignItems: "center", justifyContent: "center", paddingVertical: 60 },
  toolCallsContainer: { paddingHorizontal: spacing.lg, gap: spacing.xs, marginBottom: spacing.xs },
  toolCall: {
    backgroundColor: colors.surface,
    borderRadius: radii.sm,
    padding: spacing.sm,
    borderWidth: 1,
    borderColor: colors.border,
  },
  toolCallHeader: {
    flexDirection: "row",
    justifyContent: "space-between",
    alignItems: "center",
  },
  toolCallArgs: {
    marginTop: spacing.xs,
    fontFamily: "monospace",
    lineHeight: 16,
  },
  noticesContainer: { paddingHorizontal: spacing.lg, gap: spacing.xs, marginBottom: spacing.xs },
  notice: {
    backgroundColor: colors.bgSecondary,
    borderRadius: radii.xs,
    padding: spacing.sm,
    borderWidth: 1,
    borderColor: colors.borderSubtle,
  },
  generatingIndicator: {
    flexDirection: "row",
    justifyContent: "center",
    paddingVertical: spacing.xs,
  },
});

