          }
          // Include text from stream or from message
          if (streamingText) {
            content.push({ type: 'text', text: streamingText });
          } else if (msg?.content) {
            const msgText = msg.content.find((c) => c.type === 'text');
            if (msgText) content.push(msgText);
          }
          // Include tool_use blocks from message
          if (msg?.content) {
