    serverUrl: '',
    token: '',
    wsStatus: 'disconnected',
    serverStatus: null,
    tunnelUrl: null,
    tunnelStatus: null,

    setServerUrl: (url) => {
      set({ serverUrl: url });
      AsyncStorage.setItem(KEY_URL, url).catch(() => {});
    },
    setToken: (token) => {
      set({ token });
      AsyncStorage.setItem(KEY_TOKEN, token).catch(() => {});
