    // connection
    serverUrl: '',
    token: '',
    wsStatus: 'disconnected',
    serverStatus: null,
    tunnelUrl: null,
    tunnelStatus: null,

    setServerUrl: (url) => {
      set({ serverUrl: url });
      AsyncStorage.setItem(KEY_URL, url).catch(() => {});
