                name: String(data.toolName),
                args: '',
                status: 'running' as const,
              }],
            }));
          }
        } else if (ct === 'tool_execution_end' || ct === 'toolₑxecutionₑnd') {
          const data = event.data as Record<string, unknown> | undefined;
          if (data?.toolCallId) {
            set((s) => ({
              toolCalls: s.toolCalls.map((tc) =>
                tc.id === String(data.toolCallId) ? { ...tc, status: 'done' as const } : tc
              ),
            }));
          }
        }
        break;
      }
      case 'notice': {
        if (event.level && event.message) {
          // Skip advisor noise
          if (!event.message.includes('Advisor')) {
            set((s) => ({
              notices: [...s.notices, { level: event.level!, message: event.message! }],
            }));
          }
        }
        break;
      }
      case 'title':
      case 'title_change': {
        if (event.title) set({ sessionTitle: event.title });
        break;
      }
      case 'thinking_level_change': {
        if (event.thinkingLevel) set({ thinkingLevel: event.thinkingLevel as ThinkingLevel });
        break;
      }
      default: {
        // Silently ignore unknown event types (advisor_cost_changed, service_tier_change, etc.)
        break;
      }
    }
  };

  return {
    // connection
    serverUrl: '',
    token: '',
    wsStatus: 'disconnected',
    serverStatus: null,
    tunnelUrl: null,
    tunnelStatus: null,

    setServerUrl: (url) => {
      set({ serverUrl: url });
      AsyncStorage.setItem(KEY_URL, url).catch(() => {});
    },
    setToken: (token) => {
      set({ token });
      AsyncStorage.setItem(KEY_TOKEN, token).catch(() => {});
    },
    connect: () => {
      const { serverUrl, token } = get();
      if (!serverUrl) return;
      wsService?.disconnect();
      wsService = new WebSocketService();
      wsService.onMessage = (msg) => get().processWsEvent(msg);
      wsService.onStatusChange = (status) => {
        set({ wsStatus: status });
        if (status === 'connected') {
          get().refreshSessions();
          wsService?.send({ type: 'get_status' });
        }
      };
      wsService.connect(serverUrl, token);
    },
    disconnect: () => {
      wsService?.disconnect();
      wsService = null;
      set({ wsStatus: 'disconnected' });
    },
    startTunnel: () => {
      wsService?.send({ type: 'start_tunnel' });
      set({ tunnelStatus: 'starting' });
    },
    stopTunnel: () => {
      wsService?.send({ type: 'stop_tunnel' });
    },

    // chat
    currentSessionId: null,
    messages: [],
    streamingText: '',
    streamingThinking: '',
    isGenerating: false,
    currentModel: null,
    selectedModel: null,
    thinkingLevel: 'high' as ThinkingLevel,
    toolCalls: [],
    notices: [],
    sessionTitle: null,

    setSelectedModel: (model) => {
      set({ selectedModel: model });
      AsyncStorage.setItem(KEY_MODEL, model).catch(() => {});
    },
    setThinkingLevel: (level) => {
      set({ thinkingLevel: level });
      AsyncStorage.setItem(KEY_THINKING, level).catch(() => {});
    },

    sendMessage: (content, opts) => {
      if (!wsService) return;
      const state = get();
      const model = opts?.model ?? state.selectedModel ?? state.currentModel ?? undefined;
      const thinking = opts?.thinking ?? state.thinkingLevel ?? undefined;
      const userMessage: OmpMessage = {
        role: 'user',
        content: [{ type: 'text', text: content }],
      };
      set({
        messages: [...state.messages, userMessage],
        isGenerating: true,
        streamingText: '',
        streamingThinking: '',
        toolCalls: [],
        notices: [],
        currentModel: model ?? state.currentModel,
      });
      wsService.send({
        type: 'send',
        content,
        sessionId: state.currentSessionId ?? null,
        model,
        thinking,
        autoApprove: opts?.autoApprove,
        cwd: opts?.cwd,
      });
    },

    cancelGeneration: () => {
      wsService?.send({ type: 'cancel' });
      flushStream();
      set({ isGenerating: false });
    },

    loadSession: (sessionId) => {
      set({
        currentSessionId: sessionId,
        messages: [],
        streamingText: '',
        streamingThinking: '',
        isGenerating: false,
        toolCalls: [],
        notices: [],
        sessionTitle: null,
      });
      wsService?.send({ type: 'get_history', sessionId });
    },

    startNewSession: () => {
      set({
        currentSessionId: null,
        messages: [],
        streamingText: '',
        streamingThinking: '',
        isGenerating: false,
        toolCalls: [],
        notices: [],
        sessionTitle: null,
      });
    },

    processWsEvent: (msg) => {
      switch (msg.type) {
        case 'event':
          processEvent(msg.event, msg.sessionId);
          break;
        case 'complete':
          flushStream();
          set({ isGenerating: false });
          break;
        case 'error':
          flushStream();
          set({ isGenerating: false });
          break;
        case 'sessions':
          set({ sessions: msg.sessions, loadingSessions: false });
          break;
        case 'history':
          set({
            currentSessionId: msg.sessionId,
            messages: msg.messages,
            streamingText: '',
            streamingThinking: '',
            isGenerating: false,
            sessionTitle: msg.title || null,
          });
          break;
        case 'status':
          set({
            serverStatus: msg.status,
            tunnelUrl: msg.status.tunnelUrl,
            tunnelStatus: msg.status.tunnelStatus,
          });
          break;
        case 'tunnel':
          set({ tunnelUrl: msg.url, tunnelStatus: msg.status });
          break;
      }
    },

    // sessions
    sessions: [],
    loadingSessions: false,
    refreshSessions: () => {
      set({ loadingSessions: true });
      wsService?.send({ type: 'list_sessions' });
    },

    // hydration
    hydrate: async () => {
      try {
        const [url, token, model, thinking] = await Promise.all([
          AsyncStorage.getItem(KEY_URL),
          AsyncStorage.getItem(KEY_TOKEN),
          AsyncStorage.getItem(KEY_MODEL),
          AsyncStorage.getItem(KEY_THINKING),
        ]);
        set({
          serverUrl: url ?? '',
          token: token ?? '',
          selectedModel: model ?? null,
          thinkingLevel: (thinking as ThinkingLevel) ?? 'high',
        });
      } catch {
        // Leave defaults on read failure.
      }
    },
  };
});

