        type: 'send',
        content,
        sessionId: state.currentSessionId ?? null,
        model,
        thinking,
        autoApprove: opts?.autoApprove,
        cwd: opts?.cwd,
      });
    },

    cancelGeneration: () => {
      wsService?.send({ type: 'cancel' });
      flushStream();
      set({ isGenerating: false });
    },

    loadSession: (sessionId) => {
      set({
        currentSessionId: sessionId,
        messages: [],
        streamingText: '',
        streamingThinking: '',
        isGenerating: false,
        toolCalls: [],
        notices: [],
        sessionTitle: null,
      });
      wsService?.send({ type: 'get_history', sessionId });
    },

    startNewSession: () => {
      set({
        currentSessionId: null,
        messages: [],
        streamingText: '',
        streamingThinking: '',
        isGenerating: false,
        toolCalls: [],
        notices: [],
        sessionTitle: null,
      });
    },

    processWsEvent: (msg) => {
      switch (msg.type) {
        case 'event':
          processEvent(msg.event, msg.sessionId);
          break;
        case 'complete':
          flushStream();
          set({ isGenerating: false });
          break;
        case 'error':
          flushStream();
          set({ isGenerating: false });
          break;
        case 'sessions':
          set({ sessions: msg.sessions, loadingSessions: false });
          break;
        case 'history':
          set({
            currentSessionId: msg.sessionId,
            messages: msg.messages,
            streamingText: '',
            streamingThinking: '',
            isGenerating: false,
            sessionTitle: msg.title || null,
          });
          break;
        case 'status':
          set({
            serverStatus: msg.status,
            tunnelUrl: msg.status.tunnelUrl,
            tunnelStatus: msg.status.tunnelStatus,
          });
          break;
        case 'tunnel':
