        },
        accent: {
          primary: "#8ab4ff",
          level: 2,
        },
      },
    },

    header: {
      enabled: true,
    },

    composer: {
      placeholder: "Ask anything…",
    },

    frameTitle: "AI assistant",
  });

  return (
    <ChatKit
      control={control}
      className="h-screen w-full bg-[#0d0f12]"
    />
  );
}
```

The documented ChatKit options include `theme`, `composer`, `header`, `history`, `thread`, `widgets`, and `threadItemActions`. ([openai.github.io](https://openai.github.io/chatkit-js/api/openai/chatkit-react/type-aliases/chatkitoptions/?utm_source=openai))

### Suggested design principle

**Use color to express state, not identity.**

The model picker, user bubble, tool results, and action buttons should share a restrained accent system. The primary visual distinction should come from spacing, surface elevation, and typography—not from a different bright color for every message type.

