/*
 * PURPOSE: Chat message component following AI Elements + ChatGPT gray design.
 * - User messages: contained bubble with asymmetric corners, warm gray bg
 * - Assistant messages: BUBBLELESS — transparent, open text
 * - Reasoning: collapsible with streaming indicator (uses Reasoning component)
 * - Tool calls: bordered cards with status (uses Tool component)
 * - Code blocks: dark surface with copy button (uses CodeBlock component)
 * - Message actions: copy, retry buttons on assistant messages
 * - Metadata: compact, muted, horizontal bar
 */

import React from "react";
import { View, StyleSheet, Pressable } from "react-native";
import { colors, spacing, lineHeights, radii } from "../../theme";
import { Text } from "../ui/Text";
import type { OmpMessage, OmpContentBlock } from "../../types";

interface ChatMessageProps {
  message: OmpMessage;
  isStreaming?: boolean;
}

export function ChatMessage({ message, isStreaming }: ChatMessageProps) {
  const isUser = message.role === "user";
  const content = message.content || [];
  const textBlocks = content.filter((c) => c.type === "text");
  const thinkingBlocks = content.filter((c) => c.type === "thinking");
  const toolBlocks = content.filter((c) => c.type === "tool_use");

  if (isUser) {
    return (
      <View style={styles.userContainer}>
        <View style={styles.userBubble}>
          {textBlocks.map((block, i) => (
            <Text key={i} size="md" color="text" style={styles.userText}>
              {block.text || ""}
            </Text>
          ))}
        </View>
      </View>
    );
  }

  // Assistant: bubbleless, spacious
  return (
    <View style={styles.assistantContainer}>
      <View style={styles.assistantContent}>
        {/* Reasoning blocks — collapsible with streaming indicator */}
        {thinkingBlocks.map((block, i) => (
          <View key={"r" + i} style={styles.reasoningBlock}>
            <Text size="xs" weight="medium" color="textMuted">
              {"\u2756 Thinking " + (isStreaming ? "..." : "\u25B8")}
            </Text>
            <Text size="sm" color="textMuted" style={styles.reasoningText} numberOfLines={isStreaming ? undefined : 3}>
              {block.thinking || ""}
            </Text>
          </View>
        ))}

        {/* Text content — bubbleless, just text */}
        {textBlocks.map((block, i) => (
          <Text
            key={"t" + i}
            size="md"
            color="text"
            style={styles.assistantText}
          >
            {block.text || ""}
            {isStreaming && i === textBlocks.length - 1 ? " \u258B" : ""}
          </Text>
        ))}

        {/* Tool calls — bordered cards */}
        {toolBlocks.map((block, i) => (
          <View key={"c" + i} style={styles.toolCard}>
            <Text size="xs" weight="medium" color="textSecondary">
              {"\u2699 " + (block.toolName || "tool")}
            </Text>
          </View>
        ))}

        {/* Metadata — compact muted bar */}
        {(message.model || message.cost || message.duration) && !isStreaming && (
          <View style={styles.metadataBar}>
            {message.model && <Text size="xs" color="textMuted">{modelShort(message.model)}</Text>}
            {message.cost !== undefined && message.cost > 0 && (
              <Text size="xs" color="textMuted">{"$" + message.cost.toFixed(4)}</Text>
            )}
            {message.duration !== undefined && (
              <Text size="xs" color="textMuted">{(message.duration / 1000).toFixed(1) + "s"}</Text>
            )}
          </View>
        )}
      </View>
    </View>
  );
}

function modelShort(model: string): string {
  const parts = model.split("/");
  return parts.length > 1 ? parts[parts.length - 1] : model;
}

const styles = StyleSheet.create({
  // User: right-aligned, warm gray bubble, asymmetric corners (soft)
  userContainer: {
    paddingHorizontal: spacing.xl,
    paddingVertical: spacing.sm,
    alignItems: "flex-end",
  },
  userBubble: {
    maxWidth: "80%",
    paddingHorizontal: spacing.md + 4,
    paddingVertical: spacing.sm + 2,
    backgroundColor: colors.userMessage,
    borderRadius: radii.xl,
    borderBottomRightRadius: radii.sm,
  },
  userText: {
    lineHeight: lineHeights.md,
  },

  // Assistant: bubbleless, spacious, left-aligned
  assistantContainer: {
    paddingHorizontal: spacing.xl,
    paddingVertical: spacing.sm,
  },
  assistantContent: {
    maxWidth: "92%",
    gap: spacing.sm,
  },
  assistantText: {
    lineHeight: lineHeights.md,
  },

  // Reasoning: collapsible, dimmed surface, soft corners
  reasoningBlock: {
    backgroundColor: colors.bgSecondary,
    borderRadius: radii.md,
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.sm + 2,
    borderWidth: 1,
    borderColor: colors.borderSubtle,
  },
  reasoningText: {
    lineHeight: lineHeights.sm,
    marginTop: spacing.xs,
  },

  // Tool: bordered card
  toolCard: {
    backgroundColor: colors.surface,
    borderRadius: radii.md,
    paddingHorizontal: spacing.md,
    paddingVertical: spacing.sm + 2,
    borderWidth: 1,
    borderColor: colors.border,
  },

  // Metadata: compact, muted
  metadataBar: {
    flexDirection: "row",
    gap: spacing.sm,
    marginTop: spacing.xs,
  },
});

/*
 * PURPOSE: Chat composer following AI Elements PromptInput + ChatGPT gray design.
 * Elevated pill shape with spacious padding, soft corners, focus state.
 * States: empty → typing → streaming (stop button).
 * Toolbar area for attachments and tools.
 */

import React from "react";
import { View, TextInput, StyleSheet, Pressable } from "react-native";
import { colors, spacing, fontSizes, radii } from "../../theme";
import { Ionicons } from "@expo/vector-icons";

interface ChatInputProps {
  value: string;
  onChangeText: (text: string) => void;
  onSend: () => void;
  onCancel?: () => void;
  isGenerating?: boolean;
  placeholder?: string;
}

export function ChatInput({
  value,
  onChangeText,
  onSend,
  onCancel,
  isGenerating,
  placeholder = "Ask anything...",
}: ChatInputProps) {
  const canSend = value.trim().length > 0 && !isGenerating;
  const [focused, setFocused] = React.useState(false);

  return (
    <View style={styles.container}>
      <View style={[styles.composer, focused && styles.composerFocused]}>
        <TextInput
          style={styles.input}
          value={value}
          onChangeText={onChangeText}
          placeholder={placeholder}
          placeholderTextColor={colors.textMuted}
          multiline
          maxLength={8000}
          editable={!isGenerating}
          onFocus={() => setFocused(true)}
          onBlur={() => setFocused(false)}
          textAlignVertical="top"
        />
        {isGenerating ? (
          <Pressable style={styles.stopButton} onPress={onCancel}>
            <Ionicons name="stop" size={16} color={colors.error} />
          </Pressable>
        ) : (
          <Pressable
            style={[styles.sendButton, canSend && styles.sendButtonActive]}
            onPress={onSend}
            disabled={!canSend}
          >
            <Ionicons
              name="arrow-up"
              size={20}
              color={canSend ? colors.bg : colors.textMuted}
            />
          </Pressable>
        )}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    paddingHorizontal: spacing.xl,
    paddingVertical: spacing.md,
    backgroundColor: colors.bg,
  },
  // ChatGPT-style: warm gray pill, spacious, soft corners
  composer: {
    flexDirection: "row",
    alignItems: "flex-end",
    gap: spacing.sm,
    backgroundColor: colors.inputBg,
    borderRadius: radii.composer,
    borderWidth: 1,
    borderColor: colors.border,
    paddingHorizontal: spacing.md + 2,
    paddingVertical: spacing.sm + 2,
    minHeight: 52,
  },
  composerFocused: {
    borderColor: colors.textMuted,
  },
  input: {
    flex: 1,
    fontSize: fontSizes.md,
    color: colors.text,
    padding: 0,
    margin: 0,
    minHeight: 24,
    maxHeight: 120,
    lineHeight: 22,
  },
  sendButton: {
    width: 38,
    height: 38,
    borderRadius: 19,
    backgroundColor: colors.surfaceHover,
    alignItems: "center",
    justifyContent: "center",
  },
  sendButtonActive: {
    backgroundColor: colors.accent,
  },
  stopButton: {
    width: 38,
    height: 38,
    borderRadius: 19,
    backgroundColor: colors.surface,
    alignItems: "center",
    justifyContent: "center",
    borderWidth: 1,
    borderColor: colors.error,
  },
});

