    startNewSession,
    setSelectedModel,
    setThinkingLevel,
    setSelectedCwd,
    wsStatus,
  } = useStore();

  const sessionId = route?.params?.sessionId;

  useEffect(() => {
    if (sessionId) loadSession(sessionId);
    else startNewSession();
  }, [sessionId]);

  useEffect(() => {
    setCwdInput(selectedCwd || "");
