                >
                  <Text size="xs" weight="medium" color={thinkingLevel === lvl ? "text" : "textSecondary"}>
                    {lvl}
                  </Text>
                </Pressable>
              ))}
            </View>

            {/* Working directory */}
            <Text size="xs" weight="medium" color="textMuted" style={styles.pickerSection}>FOLDER</Text>
