curl -s -H "Authorization: Bearer $TOKEN" http://localhost:9090/api/status 2>/dev/null | python -c "import sys,json; d=json.load(sys.stdin); print(f'tunnel: {d[\"tunnelUrl\"]} status: {d[\"tunnelStatus\"]}')" 2>/dev/null || echo "Server not responding"

echo "=== WS TEST ==="
cd D:/omp-mobile/server && bun -e "
const ws = new WebSocket('ws://localhost:9090/?token=$TOKEN');
ws.onopen = () => { console.log('WS: CONNECTED'); ws.send(JSON.stringify({type:'get_status'})); };
ws.onmessage = (e) => { const m = JSON.parse(e.data); console.log('WS: got', m.type); if(m.type==='status') { console.log('WS: tunnel='+m.status.tunnelUrl+' status='+m.status.tunnelStatus); } ws.close(); };
ws.onerror = (e) => { console.log('WS: ERROR', e.message || e); };
ws.onclose = () => { console.log('WS: CLOSED'); process.exit(0); };
setTimeout(() => { console.log('WS: TIMEOUT'); process.exit(1); }, 5000);
" 2>&1

echo "=== TUNNEL WS TEST ==="
TUNNEL_URL=$(curl -s -H "Authorization: Bearer $TOKEN" http://localhost:9090/api/status 2>/dev/null | python -c "import sys,json; print(json.load(sys.stdin)['tunnelUrl'] or '')" 2>/dev/null)
echo "Tunnel URL: $TUNNEL_URL"
