      }
      case 'agent_start': {
        set({ isGenerating: true, streamingText: '', streamingThinking: '', toolCalls: [], notices: [] });
        break;
      }
      case 'turn_start': {
        break;
      }
      case 'message_start': {
        const startMsg = typeof event.message === 'string' ? undefined : event.message;
