            model: msg.model,
            usage: msg.usage,
            cost: msg.cost ?? event.cost,
            duration: msg.duration ?? event.duration,
            ttft: msg.ttft ?? event.ttft,
          };
          set((s) => ({ messages: [...s.messages, finalized] }));
