      }
      case 'turn_end': {
        break;
      }
      case 'agent_end': {
        flushStream();
        set({ isGenerating: false });
        break;
      }
      case 'custom': {
        const ct = event.customType || (event.data && (event.data as Record<string, unknown>).customType) || '';
