        break;
      }
      default: {
        // Silently ignore unknown event types (advisor_cost_changed, service_tier_change, etc.)
        break;
      }
    }
  };

  return {
    // connection
    serverUrl: '',
    token: '',
    wsStatus: 'disconnected',
    serverStatus: null,
    tunnelUrl: null,
    tunnelStatus: null,

    setServerUrl: (url) => {
    setToken: (token) => {
