details.oldText:
/*
 * PURPOSE: Sessions screen — list of past OMP conversations.
 * Tap a session to open it in the Chat screen.
 *
 * KEY DECISIONS:
 * - Shows a loading state while the first list_sessions round-trip is in flight
 *   (previously flashed "No sessions yet" while the server parsed 600+ files).
 * - Timestamps from OMP session filenames encode time with dashes
 *   (2026-05-07T11-42-14); formatDate restores colons before parsing.
 */

import React, { useState, useEffect } from "react";
import { View, StyleSheet, FlatList, Pressable, RefreshControl } from "react-native";
import { colors, spacing } from "../theme";
import { Text } from "../components/ui/Text";
import { Card } from "../components/ui/Card";
import { Badge } from "../components/ui/Badge";
import { Stack } from "../components/ui/Stack";
import { Icon } from "../components/ui/Icon";
import { useStore } from "../store";
import { openChat } from "../navigation";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import type { SessionSummary } from "../types";
import type { NavigationProp } from "../navigation";

export function SessionsScreen({ navigation }: { navigation: NavigationProp }) {
  const insets = useSafeAreaInsets();
  const { sessions, refreshSessions, wsStatus, loadingSessions } = useStore();
  const [refreshing, setRefreshing] = useState(false);

  useEffect(() => {
    refreshSessions();
  }, []);

  const handleRefresh = async () => {
    setRefreshing(true);
    await refreshSessions();
    setRefreshing(false);
  };

  const handleOpenSession = (session: SessionSummary) => {
    openChat(session.id);
  };

  const renderItem = ({ item }: { item: SessionSummary }) => (
    <Pressable onPress={() => handleOpenSession(item)} style={styles.sessionItem}>
      <Card padding="md">
        <Stack gap="xs">
          <View style={styles.headerRow}>
            <Text size="md" weight="medium" color="text" numberOfLines={1} style={styles.title}>
              {item.title || "Untitled"}
            </Text>
            <Badge size="sm" variant="light">
              {item.messageCount} msgs
            </Badge>
          </View>
          <Text size="xs" color="textMuted" numberOfLines={1}>
            {item.cwd}
          </Text>
          <Text size="xs" color="textMuted">
            {formatDate(item.timestamp)}
          </Text>
        </Stack>
      </Card>
    </Pressable>
  );

  if (wsStatus !== "connected") {
    return (
      <View style={styles.empty}>
        <Icon name="cloud-offline" size={36} color={colors.textMuted} />
        <Text size="md" color="textMuted" style={{ marginTop: spacing.md }}>
          Not connected to server
        </Text>
      </View>
    );
  }

  if (loadingSessions && sessions.length === 0) {
    return (
      <View style={styles.empty}>
        <Icon name="sync" size={28} color={colors.textMuted} />
        <Text size="md" color="textMuted" style={{ marginTop: spacing.md }}>
          Loading sessions…
        </Text>
      </View>
    );
  }

  if (sessions.length === 0) {
    return (
      <View style={styles.empty}>
        <Icon name="chat-outline" size={36} color={colors.textMuted} />
        <Text size="md" color="textMuted" style={{ marginTop: spacing.md }}>
          No sessions yet
        </Text>
      </View>
    );
  }

  return (
    <FlatList
      data={sessions}
      keyExtractor={(item) => item.id}
      renderItem={renderItem}
      style={{ backgroundColor: colors.bg }}
      contentContainerStyle={[styles.list, { paddingTop: Math.max(insets.top + spacing.sm, spacing.lg) }]}
      refreshControl={
        <RefreshControl refreshing={refreshing} onRefresh={handleRefresh} tintColor={colors.accent} />
      }
    />
  );
}

function formatDate(timestamp: string): string {
  try {
    // OMP session filenames encode time with dashes (2026-05-07T11-42-14);
    // restore colons so Date can parse it.
    const normalized = timestamp.replace(/T(\d{2})-(\d{2})-(\d{2})/, "T$1:$2:$3");
    const d = new Date(normalized);
    return d.toLocaleDateString("en-US", { month: "short", day: "numeric", hour: "numeric", minute: "2-digit" });
  } catch {
    return String(timestamp);
  }
}

const styles = StyleSheet.create({
  list: {
    padding: spacing.lg,
    gap: spacing.sm,
    paddingBottom: 100,
  },
  sessionItem: {
    marginBottom: 0,
  },
  headerRow: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    gap: spacing.sm,
  },
  title: {
    flex: 1,
  },
  empty: {
    flex: 1,
    alignItems: "center",
    justifyContent: "center",
    backgroundColor: colors.bg,
  },
});

