base = os.path.expanduser("~/.omp/agent/sessions")
# find a C--tmp session file
files = []
for d in os.listdir(base):
    if d.startswith("--C--tmp") or "tmp" in d:
        for f in os.listdir(os.path.join(base,d)):
            if f.endswith(".jsonl") and "__advisor" not in f:
                files.append(os.path.join(base,d,f))
files.sort(key=os.path.getmtime)
p = files[-1]
print("file", p)
for line in open(p, encoding="utf-8", errors="replace"):
    line=line.strip()
    if not line: continue
    try: o=json.loads(line)
    except: continue
    if o.get("type")=="message":
        m=o["message"]
        print("ROLE", m.get("role"), "content-type", type(m.get("content")).__name__)
        c=m.get("content")
        if isinstance(c,list):
            for b in c[:3]:
                print("   block keys:", list(b.keys()) if isinstance(b,dict) else b, "type=", b.get("type") if isinstance(b,dict) else None)
        else:
            print("   content:", str(c)[:120])

