/*
 * PURPOSE: Markdown + LaTeX renderer for assistant messages, backed by
 * react-native-enriched-markdown (Software Mansion): fully native text (no
 * WebView), CommonMark + GFM (tables, task lists, strikethrough), LaTeX math
 * (block $$...$$ with flavor="github", inline $...$), tree-sitter code
 * highlighting, and streaming support.
 *
 * KEY DECISIONS:
 * - Dark theme matched to the app palette: body #f2f2f2 / secondary #b5b5b5,
 *   code blocks on #1b1b1b with #2f2f2f border (reference args-box look),
 *   links in the soft blue #9ccafa.
 * - flavor="github" so $$ block math parses; inline $...$ works in all flavors.
 * - onLinkPress opens via Linking (no in-app browser dependency).
 * - Requires Fabric (enabled in this project) and the vendored native assets
 *   restored by the package postinstall (run manually if npm blocks scripts).
 */

import React from "react";
import { Linking, StyleSheet, View } from "react-native";
import { EnrichedMarkdownText } from "react-native-enriched-markdown";
import type { MarkdownStyle } from "react-native-enriched-markdown";
import { colors } from "../../theme";

const MONO = "monospace";

const markdownStyle: MarkdownStyle = {
  paragraph: { color: colors.text, fontSize: 15, lineHeight: 23, marginBottom: 10 },
  h1: { color: colors.text, fontSize: 22, lineHeight: 28, marginTop: 6, marginBottom: 8 },
  h2: { color: colors.text, fontSize: 19, lineHeight: 25, marginTop: 6, marginBottom: 6 },
  h3: { color: colors.text, fontSize: 17, lineHeight: 23, marginTop: 4, marginBottom: 4 },
  h4: { color: colors.text, fontSize: 16, lineHeight: 22, marginTop: 4, marginBottom: 4 },
  h5: { color: colors.textSecondary, fontSize: 15, lineHeight: 21, marginTop: 2, marginBottom: 2 },
  h6: { color: colors.textSecondary, fontSize: 14, lineHeight: 20, marginTop: 2, marginBottom: 2 },
  strong: { color: colors.text },
  em: { color: colors.textSecondary },
  strikethrough: { color: colors.textMuted },
  link: { color: colors.link, underline: true },
  code: {
    fontFamily: MONO,
    fontSize: 13,
    color: colors.text,
    backgroundColor: colors.card,
    borderColor: colors.borderSubtle,
  },
  codeBlock: {
    backgroundColor: "#1b1b1b",
    borderColor: "#2f2f2f",
    borderWidth: 1,
    borderRadius: 10,
    padding: 10,
    marginBottom: 10,
    syntaxColors: {
      keyword: "#c792ea",
      operator: "#89ddff",
      punctuation: "#9b9b9b",
      string: "#c3e88d",
      number: "#f78c6c",
      constant: "#f78c6c",
      comment: "#6f6f6f",
      function: "#82aaff",
      type: "#ffcb6b",
      variable: "#f2f2f2",
      property: "#9ccafa",
      tag: "#f07178",
      attribute: "#ffcb6b",
      embedded: "#89ddff",
    },
  },
  blockquote: {
    borderColor: colors.border,
    borderWidth: 2,
    backgroundColor: colors.surface,
    borderRadius: 8,
    padding: 8,
    color: colors.textSecondary,
    marginBottom: 10,
  },
  list: { bulletColor: colors.textMuted, bulletSize: 5, itemSpacing: 4, marginBottom: 10 },
  thematicBreak: { borderColor: colors.borderSubtle, borderWidth: 1 },
  math: { color: colors.text, fontSize: 15, marginBottom: 10 },
  inlineMath: { color: colors.text, fontSize: 15 },
};

export interface MarkdownViewProps {
  markdown: string;
  isStreaming?: boolean;
}

export function MarkdownView({ markdown, isStreaming }: MarkdownViewProps) {
  return (
    <View style={styles.wrap}>
      <EnrichedMarkdownText
        markdown={markdown}
        flavor="github"
        markdownStyle={markdownStyle}
        streamingAnimation={!!isStreaming}
        onLinkPress={(event) => {
          if (event.url) Linking.openURL(event.url).catch(() => {});
        }}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { marginTop: 2 },
});

