/*
 * PURPOSE: Markdown + LaTeX rendering for assistant messages on Expo SDK 53
 * (RN 0.79), using a pure-JS stack:
 *   - react-native-marked (marked/markdown-it lineage) for CommonMark+GFM.
 *   - react-native-math-view (MathJax -> react-native-svg) for LaTeX, no WebView.
 *
 * HISTORY:
 * - react-native-enriched-markdown (native md4c/RaTeX) was tried first but its
 *   codegen spec fails on RN 0.79 ("Unknown prop type for fontSize"); it needs
 *   a newer RN. Removed; revisit after an SDK upgrade.
 *
 * KEY DECISIONS:
 * - Block math ($$...$$) is split OUT of the markdown and rendered as MathView
 *   between markdown chunks; inline $...$ is split inside text nodes by the
 *   custom renderer so formulas flow with the paragraph.
 * - Dark theme via the `styles` prop (direct TextStyle/ViewStyle per element).
 * - Code blocks render in the reference args-box look (#1b1b1b / #2f2f2f).
 */

import React from "react";
import { View, Text as RNText, StyleSheet, Linking } from "react-native";
import Markdown, { Renderer } from "react-native-marked";
import type { MarkedStyles } from "react-native-marked";
import MathView from "react-native-math-view";
import { colors } from "../../theme";

const MONO = "monospace";

const styles: MarkedStyles = {
  text: { color: colors.text, fontSize: 15, lineHeight: 23 },
  paragraph: { marginBottom: 10 },
  h1: { color: colors.text, fontSize: 22, lineHeight: 28, marginTop: 6, marginBottom: 8 },
  h2: { color: colors.text, fontSize: 19, lineHeight: 25, marginTop: 6, marginBottom: 6 },
  h3: { color: colors.text, fontSize: 17, lineHeight: 23, marginTop: 4, marginBottom: 4 },
  h4: { color: colors.text, fontSize: 16, lineHeight: 22, marginTop: 4, marginBottom: 4 },
  h5: { color: colors.textSecondary, fontSize: 15, lineHeight: 21 },
  h6: { color: colors.textSecondary, fontSize: 14, lineHeight: 20 },
  strong: { color: colors.text, fontWeight: "600" },
  em: { color: colors.textSecondary },
  strikethrough: { color: colors.textMuted },
  link: { color: colors.link },
  codespan: {
    fontFamily: MONO,
    fontSize: 13,
    color: colors.text,
    backgroundColor: colors.card,
  },
  code: {
    backgroundColor: "#1b1b1b",
    borderColor: "#2f2f2f",
    borderWidth: 1,
    borderRadius: 10,
    padding: 10,
    marginBottom: 10,
  },
  blockquote: {
    borderColor: colors.border,
    borderLeftWidth: 2,
    backgroundColor: colors.surface,
    borderRadius: 8,
    padding: 8,
    marginBottom: 10,
  },
  li: { color: colors.textSecondary, fontSize: 15, lineHeight: 22 },
  hr: { backgroundColor: colors.borderSubtle, height: 1, marginVertical: 10 },
};

/** Render inline $...$ math inside a text node; plain text passes through. */
function renderInlineMath(text: string): React.ReactNode {
  const parts = text.split(/(\$[^$\n]+\$)/g);
  if (parts.length === 1) return text;
  return parts.map((part, i) => {
    const m = part.match(/^\$([^$\n]+)\$$/);
    if (m) {
      return (
        <MathView
          key={i}
          math={m[1]}
          textStyle={{ color: colors.text, fontSize: 15 }}
        />
      );
    }
    return part;
  });
}

class ChatRenderer extends Renderer {
  code(text: string, language?: string): React.ReactNode {
    return (
      <View style={styles.code} key={this.getKey()}>
        <RNText style={{ fontFamily: MONO, fontSize: 13, color: colors.textSecondary, lineHeight: 19 }}>
          {text}
        </RNText>
      </View>
    );
  }

  text(text: string | React.ReactNode[], textStyles?: object): React.ReactNode {
    if (typeof text === "string") {
      return (
        <RNText key={this.getKey()} style={styles.text}>
          {renderInlineMath(text)}
        </RNText>
      );
    }
    return super.text(text, textStyles as never);
  }

  link(children: string | React.ReactNode[], href: string): React.ReactNode {
    return (
      <RNText
        key={this.getKey()}
        style={[styles.text, styles.link]}
        onPress={() => Linking.openURL(href).catch(() => {})}
      >
        {children}
      </RNText>
    );
  }
}

type Segment = { kind: "md"; text: string } | { kind: "math"; tex: string };

/** Split block math ($$...$$) out of the markdown stream. */
function splitBlockMath(md: string): Segment[] {
  const segments: Segment[] = [];
  const re = /\$\$([\s\S]+?)\$\$/g;
  let last = 0;
  let m: RegExpExecArray | null;
  while ((m = re.exec(md)) !== null) {
    if (m.index > last) segments.push({ kind: "md", text: md.slice(last, m.index) });
    segments.push({ kind: "math", tex: m[1].trim() });
    last = m.index + m[0].length;
  }
  if (last < md.length) segments.push({ kind: "md", text: md.slice(last) });
  return segments;
}

const renderer = new ChatRenderer();

export interface MarkdownViewProps {
  markdown: string;
  isStreaming?: boolean;
}

export function MarkdownView({ markdown }: MarkdownViewProps) {
  const segments = splitBlockMath(markdown);
  return (
    <View style={wrap.wrap}>
      {segments.map((seg, i) =>
        seg.kind === "math" ? (
          <View key={i} style={wrap.mathBlock}>
            <MathView math={seg.tex} textStyle={{ color: colors.text, fontSize: 16 }} />
          </View>
        ) : (
          <Markdown key={i} value={seg.text} styles={styles} renderer={renderer} />
        ),
      )}
    </View>
  );
}

const wrap = StyleSheet.create({
  wrap: { marginTop: 2 },
  mathBlock: { marginVertical: 8, alignItems: "center" },
});

