          sessionId = obj.id;
          if (obj.timestamp) timestamp = obj.timestamp;
        }
        if (!firstUserText && obj.type === "message" && obj.message?.role === "user") {
          firstUserText = extractText(obj.message.content);
        }
      } catch {
        // Skip non-JSON lines
      }
      if (title && firstUserText) break;
    }
    if (!title) title = firstUserText || "Untitled";
    if (title.length > 48) title = title.slice(0, 48) + "…";

    if (!sessionId) return null;
    return { title, sessionId, timestamp, messageCount };
  } catch {
    return null;
  }
}

/**
 * List all OMP sessions, sorted newest first.
 */
export async function listSessions(): Promise<SessionSummary[]> {
  const sessions: SessionSummary[] = [];

  let cwdDirs: Dirent[];
  try {
    cwdDirs = readdirSync(SESSIONS_DIR, { withFileTypes: true });
  } catch {
    return [];
  }

  for (const dir of cwdDirs) {
    if (!dir.isDirectory()) continue;

    const dirPath = join(SESSIONS_DIR, dir.name);
    const cwd = decodeCwd(dir.name);

    let files: string[];
    try {
      files = readdirSync(dirPath).filter(
        (f) => f.endsWith(".jsonl") && !f.includes("__advisor"),
      );
    } catch {
      continue;
    }

    for (const file of files) {
      const filePath = join(dirPath, file);
      let size: number;
      let mtimeMs: number;
      try {
        const st = statSync(filePath);
        size = st.size;
        mtimeMs = st.mtimeMs;
      } catch {
        continue;
      }

      const header = await parseSessionFileCached(filePath, mtimeMs, size);
      if (!header) continue;

      sessions.push({
        id: header.sessionId,
        title: header.title,
        timestamp: header.timestamp,
        cwd,
        messageCount: header.messageCount,
        size,
      });
    }
  }

  sessions.sort((a, b) => {
    const parseTs = (ts: string): number => {
      // Filenames encode time with dashes (2026-05-07T11-42-14); restore colons
      // or Date parses to NaN and the sort order becomes arbitrary.
      const normalized = ts.replace(/T(\d{2})-(\d{2})-(\d{2})/, "T$1:$2:$3");
      const t = new Date(normalized).getTime();
      return Number.isFinite(t) ? t : 0;
    };
    return parseTs(b.timestamp) - parseTs(a.timestamp);
  });

  return sessions;
}

/**
 * Find a session JSONL file by session ID.
 */
async function findSessionFile(sessionId: string): Promise<string | null> {
  let cwdDirs: Dirent[];
  try {
    cwdDirs = readdirSync(SESSIONS_DIR, { withFileTypes: true });
  } catch {
    return null;
  }

  for (const dir of cwdDirs) {
    if (!dir.isDirectory()) continue;

    const dirPath = join(SESSIONS_DIR, dir.name);
    let files: string[];
    try {
      files = readdirSync(dirPath).filter(
        (f) => f.endsWith(".jsonl") && !f.includes("__advisor"),
      );
    } catch {
      continue;
    }

    for (const file of files) {
      if (file.includes(sessionId)) {
        return join(dirPath, file);
      }
    }
  }

  return null;
}

/**
 * Get full message history for a session.
 */
export async function getSessionHistory(
  sessionId: string,
): Promise<{ messages: OmpMessage[]; title: string } | null> {
  const filePath = await findSessionFile(sessionId);
  if (!filePath) return null;

  try {
    const text = await Bun.file(filePath).text();
    const lines = text.split("\n").filter((l) => l.trim());
    const messages: OmpMessage[] = [];
    let title = "Untitled";

    for (const line of lines) {
      try {
        const obj = JSON.parse(line);
        if (obj.type === "title" && obj.title) {
          title = obj.title;
        } else if (obj.type === "message" && obj.message) {
          messages.push(obj.message as OmpMessage);
        }
      } catch {
        // Skip non-JSON lines
      }
    }

    return { messages, title };
  } catch {
    return null;
  }
}

/**
 * Delete a session: removes its JSONL plus any advisor sidecar files.
 */
export function deleteSession(sessionId: string): boolean {
  try {
    const filePath = findSessionFileSync(sessionId);
    if (!filePath) return false;
    const dir = filePath.split(sep).slice(0, -1).join(sep);
    for (const f of readdirSync(dir)) {
      if (f.includes(sessionId)) {
        try {
          unlinkSync(join(dir, f));
        } catch {
          // best effort
        }
      }
    }
    return true;
  } catch {
    return false;
  }
}

/** Sync variant of findSessionFile for delete/fork paths. */
function findSessionFileSync(sessionId: string): string | null {
  try {
    for (const dir of readdirSync(SESSIONS_DIR, { withFileTypes: true })) {
      if (!dir.isDirectory()) continue;
      const dirPath = join(SESSIONS_DIR, dir.name);
      for (const f of readdirSync(dirPath)) {
        if (f.endsWith(".jsonl") && f.includes(sessionId) && !f.includes("__advisor")) {
          return join(dirPath, f);
        }
      }
    }
    return null;
  } catch {
    return null;
  }
}

/**
 * Fork a session: copy the header + first `messageCount` message lines into a
 * new session file (new id/timestamp) in the same cwd directory.
 * Returns the new session id, or null on failure.
 */
export function forkSession(sessionId: string, messageCount: number): string | null {
  try {
    const filePath = findSessionFileSync(sessionId);
    if (!filePath) return null;
    const text = Bun.file ? undefined : undefined; // placeholder removed below
    return null;
  } catch {
    return null;
  }
}

