  const [height, setHeight] = React.useState(60);
  return (
    <WebView
      source={{ html: katexHtml(tex) }}
      style={{
        height,
        backgroundColor: "#1b1b1b",
        borderColor: "#2f2f2f",
        borderWidth: 1,
        borderRadius: 10,
      }}
      scrollEnabled={false}
      javaScriptEnabled
      onMessage={(e) => {
        const h = parseInt(e.nativeEvent.data, 10);
        if (Number.isFinite(h) && h > 0) setHeight(h + 4);
