/*
 * PURPOSE: Anchored popover menu matching the reference design: a rounded
 * surface card (#2d2d2d, 14px radius, shadow) floating above the composer,
 * with rows of icon + label and an optional blue check on the selected row.
 *
 * Used for: attach menu (+), approval-mode menu (shield). The context popover
 * is custom (progress + stat rows) and lives in ContextPopover.tsx.
 */

import React from "react";
import { View, StyleSheet, Pressable } from "react-native";
import { colors, spacing, radii } from "../../theme";
import { Text } from "../ui/Text";
import { Icon, type IconName } from "../ui/Icon";

export interface PopoverItem {
  label: string;
  icon?: IconName;
  checked?: boolean;
  onPress: () => void;
}

export interface PopoverMenuProps {
  visible: boolean;
  onClose: () => void;
  items: PopoverItem[];
  /** Horizontal anchor of the card relative to the composer. */
  align?: "left" | "right";
}

export function PopoverMenu({ visible, onClose, items, align = "left" }: PopoverMenuProps) {
  if (!visible) return null;
  return (
    <View style={styles.root} pointerEvents="box-none">
      <Pressable style={styles.scrim} onPress={onClose} />
      <View style={[styles.card, align === "left" ? styles.cardLeft : styles.cardRight]}>
        {items.map((item, i) => (
          <Pressable
            key={item.label}
            style={styles.row}
            onPress={() => {
              item.onPress();
              onClose();
            }}
          >
            {item.icon ? (
              <Icon name={item.icon} size={16} color={colors.textMuted} />
            ) : null}
            <Text size="sm" color="text" style={styles.label}>
              {item.label}
            </Text>
            {item.checked ? (
              <Icon name="check" size={15} color={colors.link} />
            ) : null}
          </Pressable>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  root: { ...StyleSheet.absoluteFillObject },
  scrim: { ...StyleSheet.absoluteFillObject },
  card: {
    position: "absolute",
    bottom: 0,
    minWidth: 200,
    backgroundColor: colors.card,
    borderRadius: 14,
    paddingVertical: spacing.xs,
    paddingHorizontal: spacing.xs,
    // soft shadow like the reference popovers
    shadowColor: "#000",
    shadowOpacity: 0.45,
    shadowRadius: 16,
    shadowOffset: { width: 0, height: 6 },
    elevation: 8,
  },
  cardLeft: { left: spacing.md },
  cardRight: { right: spacing.md },
  row: {
    flexDirection: "row",
    alignItems: "center",
    gap: spacing.sm,
    paddingVertical: 10,
    paddingHorizontal: spacing.md,
    borderRadius: radii.sm,
  },
  label: { flex: 1 },
});

