                  <View style={styles.node}>
                    <Icon
                      name={step.kind === "reasoning" ? "sparkle" : "wrench"}
                      size={11}
                      color="#8e8e8e"
                    />
                  </View>
                  {!last && <View style={styles.rail} />}
