        <Animated.View
          style={{
            transform: [
              {
                rotate: rotate.interpolate({
                  inputRange: [0, 1],
                  outputRange: ["0deg", "180deg"],
                }),
              },
            ],
          }}
        >
          <Icon name="chevron-down" size={13} color={colors.link} />
        </Animated.View>
      </Pressable>
      {open && (
        <View>
          {step.args ? (
            <>
