 * model sheet: grabber, "MODEL" title (13/600 ls .07em #7c7c7c), rows with
 * 17/600 name + 13.5 #8a8a8a desc + blue check on selected, padding 13/12 r13.
 * Below MODEL we keep our REASONING segmented control and FOLDER input, styled
 * to match (they have no reference equivalent but share the sheet chrome).
 */

import React, { useEffect, useState } from "react";
import { View, StyleSheet, Pressable, ScrollView, Text as RNText } from "react-native";
import { Sheet } from "../ui/Sheet";
import { Input } from "../ui/Input";
import { Icon } from "../ui/Icon";
import { colors, spacing, radii } from "../../theme";
import { useStore } from "../../store";
import { MODEL_PRESETS, THINKING_LEVELS, type ThinkingLevel } from "../../types";

export interface ModelSheetProps {
  visible: boolean;
  onClose: () => void;
}

export function ModelSheet({ visible, onClose }: ModelSheetProps) {
  const {
    selectedModel,
    setSelectedModel,
    thinkingLevel,
    setThinkingLevel,
    selectedCwd,
    setSelectedCwd,
  } = useStore();
  const [cwdInput, setCwdInput] = useState(selectedCwd || "");

  useEffect(() => {
    if (visible) setCwdInput(selectedCwd || "");
  }, [visible, selectedCwd]);

  return (
    <Sheet visible={visible} onClose={onClose}>
      <ScrollView bounces={false} showsVerticalScrollIndicator={false}>
        <RNText style={styles.sectionTitle}>MODEL</RNText>
        {MODEL_PRESETS.map((m) => (
          <Pressable
            key={m.value}
            style={({ pressed }) => [styles.modelRow, pressed && styles.modelRowPressed]}
            onPress={() => {
              setSelectedModel(m.value);
              onClose();
            }}
          >
            <View style={styles.modelText}>
              <RNText style={styles.modelName}>{m.label}</RNText>
              {m.desc ? <RNText style={styles.modelDesc}>{m.desc}</RNText> : null}
            </View>
            {selectedModel === m.value ? (
              <Icon name="check" size={20} color={colors.link} />
            ) : null}
          </Pressable>
        ))}

        <RNText style={[styles.sectionTitle, styles.sectionGap]}>REASONING</RNText>
        <View style={styles.segmented}>
          {THINKING_LEVELS.map((lvl) => (
            <Pressable
              key={lvl}
              style={[styles.segment, thinkingLevel === lvl && styles.segmentActive]}
              onPress={() => setThinkingLevel(lvl as ThinkingLevel)}
            >
              <RNText
                style={[
                  styles.segmentText,
                  thinkingLevel === lvl && styles.segmentTextActive,
                ]}
              >
                {lvl}
              </RNText>
            </Pressable>
          ))}
        </View>

        <RNText style={[styles.sectionTitle, styles.sectionGap]}>FOLDER</RNText>
        <Input
          value={cwdInput}
          onChangeText={setCwdInput}
          placeholder="e.g. D:/projects/app"
          autoCapitalize="none"
          autoCorrect={false}
        />
        <Pressable
          style={styles.applyFolder}
          onPress={() => {
            setSelectedCwd(cwdInput.trim() || "");
            onClose();
          }}
        >
          <RNText style={styles.applyFolderText}>Use this folder</RNText>
        </Pressable>
      </ScrollView>
    </Sheet>
  );
}

const styles = StyleSheet.create({
  sectionTitle: {
    fontSize: 13,
    fontWeight: "600",
    letterSpacing: 0.9,
    color: "#7c7c7c",
    paddingHorizontal: 12,
    paddingBottom: 8,
  },
  sectionGap: { marginTop: spacing.lg },
  modelRow: {
    flexDirection: "row",
    alignItems: "center",
    gap: 12,
    paddingVertical: 13,
    paddingHorizontal: 12,
    borderRadius: 13,
  },
  modelRowPressed: { backgroundColor: "#2c2c2c" },
  modelText: { flex: 1 },
  modelName: { fontSize: 17, fontWeight: "600", color: colors.text },
  modelDesc: { fontSize: 13.5, color: "#8a8a8a", marginTop: 2 },
  segmented: {
    flexDirection: "row",
    backgroundColor: "#1b1b1b",
    borderRadius: radii.md,
    padding: 3,
    gap: 2,
    marginHorizontal: 12,
  },
  segment: {
    flex: 1,
    alignItems: "center",
    paddingVertical: 8,
    borderRadius: radii.sm,
  },
  segmentActive: { backgroundColor: "#2d2d2d" },
  segmentText: { fontSize: 13, color: colors.textMuted, fontWeight: "500" },
  segmentTextActive: { color: colors.text },
  applyFolder: {
    alignItems: "center",
    paddingVertical: 11,
    borderRadius: radii.md,
    backgroundColor: "#2d2d2d",
    marginTop: spacing.sm,
    marginHorizontal: 12,
    marginBottom: spacing.sm,
  },
  applyFolderText: { fontSize: 14, fontWeight: "500", color: colors.text },
});
