  bottomInset = 0,
  modelLabel,
  onOpenModel,
  onAttachFiles,
  onTakePhoto,
  onPasteLink,
}: ChatInputProps) {
  const [panel, setPanel] = useState<Panel>(null);
  const [listening, setListening] = useState(false);
  const { approvalMode, setApprovalMode, attachments, clearAttachments, lastUsage } = useStore();

  const canSend = value.trim().length > 0 && !isGenerating;

  useEffect(() => {
    const onResults = (e: SpeechResults) => {
      const text = e.value?.join(" ") ?? "";
      if (text) onChangeText((value ? value + " " : "") + text);
    };
    Voice.onResults = onResults;
    return () => {
      Voice.onResults = undefined;
    };
  }, [value, onChangeText]);

