              label: "Ask before running",
              checked: approvalMode === "ask",
              onPress: () => setApprovalMode("ask"),
            },
            {
              label: "Read-only mode",
              checked: approvalMode === "readonly",
              onPress: () => setApprovalMode("readonly"),
