            <Icon name="add" size={24} color="#a3a3a3" />
          </Pressable>
          <Pressable
            style={styles.shieldGroup}
            onPress={() => setPanel(panel === "shield" ? null : "shield")}
            accessibilityLabel="Tool approval mode"
          >
