  useEffect(() => {
    if (!isGenerating) return;
    const id = setInterval(() => {
      listRef.current?.scrollToEnd({ animated: false });
    }, 250);
    return () => clearInterval(id);
  }, [isGenerating]);

  const handleScroll = (event: {
    nativeEvent: {
      contentOffset: { y: number };
