                </>
              ) : steps.length === 0 ? (
                <RNText style={styles.emptyResponse}>(empty response)</RNText>
              ) : null}
            </View>
          );
        }}
        ListFooterComponent={
          isGenerating ? (
            <View style={styles.turn}>
              <Trace steps={liveSteps} isStreaming />
              <Trace steps={liveSteps as TraceStep[]} isStreaming />
