                  <Text key={i} size="xs" color="textMuted">
                    {n.message}
                  </Text>
                ))}
              </View>
            )}
          </>
        }
        renderItem={({ item }) => {
          if (item.kind === "user") {
            return <ChatMessage message={item.msg} />;
          }
          const steps = buildSteps(item.turn);
          const text = turnText(item.turn);
          const meta = turnMeta(item.turn);
          return (
            <View style={styles.turn}>
