    flexDirection: "row",
    alignItems: "center",
    justifyContent: "space-between",
    paddingHorizontal: spacing.lg,
    paddingBottom: spacing.sm,
    backgroundColor: colors.bg,
  },
  title: { flex: 1, textAlign: "center", paddingHorizontal: spacing.sm },
  settingsWrap: { flex: 1 },
});

