                    {step.kind === "reasoning" ? (
                      <>
                        <RNText style={styles.traceLabel}>
                          {"Reasoning" + (step.dur ? " · " + step.dur : "")}
                        </RNText>
                        <RNText style={styles.traceText}>{step.text}</RNText>
