                    )}
                  </View>
                </View>
              </FadeIn>
            );
          })}
          {showThinkingNode && (
            <View style={styles.entry}>
              <View style={styles.node}>
                <Icon name="sync" size={11} color="#8e8e8e" />
              </View>
              <View style={styles.entryBody}>
                <RNText style={styles.traceText}>thinking…</RNText>
              </View>
            </View>
          )}
        </View>
      )}
    </View>
  );
}

