  emptyResponse: { color: colors.textMuted, fontSize: 14, marginTop: spacing.sm },
  actions: { flexDirection: "row", alignItems: "center", gap: 14, marginTop: 18 },
  scrollButton: {
    position: "absolute",
    bottom: spacing.lg,
    alignSelf: "center",
    width: 36,
    height: 36,
    borderRadius: 18,
    backgroundColor: colors.surface,
    borderWidth: 1,
    borderColor: colors.border,
