/**
 * scrub-images — omp extension entry.
 *
 * `/scrub-images` opens a custom multi-select TUI widget listing every image
 * in the current session (inspectᵢmage calls/results + user-attached image
 * blocks). Toggle many with space, then Test selected (re-send the context
 * with those images stripped to the current provider — 200 = safe to remove,
 * 400 = still triggering) or Remove selected (stub them out of the session
 * JSONL, backed up first). Loops with status feedback until Done/Esc.
 */

import type { ExtensionAPI, ExtensionCommandContext } from "@oh-my-pi/pi-coding-agent";
import { scanImages } from "./image-scanner.js";
import { runTest } from "./test-runner.js";
import { removeImage } from "./session-editor.js";
import { ScrubImagesWidget, type ScrubResult } from "./widget.js";

export default function (pi: ExtensionAPI) {
  pi.setLabel("Scrub Images");
  pi.registerCommand("scrub-images", {
    description:
      "List images in this session, multi-select, test provider acceptance with them stripped, or remove them",
    handler: async (_args, ctx) => {
      await scrubImagesFlow(ctx);
    },
  });
}

async function scrubImagesFlow(ctx: ExtensionCommandContext): Promise<void> {
  let status = "";
  for (;;) {
    const images = scanImages(ctx);
    if (images.length === 0) {
      ctx.ui.notify(
        "No images found in this session." + (status ? " " + status : ""),
        "info",
      );
      return;
    }

    const result = await ctx.ui.custom<ScrubResult>(
      (tui, theme, _kb, done) =>
        new ScrubImagesWidget(tui, theme, images, status, done),
    );

    if (!result || result.action === "done") return;

    const selected = result.selected;
    if (selected.length === 0) {
      status = "No images selected — toggle some with space first.";
      continue;
    }

    if (result.action === "test") {
      ctx.ui.notify(
        `Testing ${selected.length} image(s) stripped from context…`,
        "info",
      );
      const r = await runTest(ctx, selected);
      if (r.ok) {
        status = `✅ Provider accepted the context with ${selected.length} image(s) stripped — safe to remove.`;
        ctx.ui.notify(status, "info");
      } else {
        status = `❌ Still rejected: ${r.error ?? "unknown error"}`;
        ctx.ui.notify(status, "warning");
      }
    } else if (result.action === "remove") {
      for (const img of selected) await removeImage(ctx, img);
      status = `Removed ${selected.length} image(s) (JSONL backed up). Resume/restart the session to apply.`;
    }
