const fs=require('fs'),path=require('path');
const root=process.cwd();
let target=null;
for(const d of fs.readdirSync(root)){
  const dp=path.join(root,d); let st; try{st=fs.statSync(dp)}catch{continue}
  if(!st.isDirectory()) continue;
  for(const f of fs.readdirSync(dp)){
    if(!f.endsWith('.jsonl')||f.includes('advisor')) continue;
    const fp=path.join(dp,f);
    const head=fs.readFileSync(fp,'utf8').slice(0,4000);
    if(head.includes('Test app connection and push GitHub')){ target=fp; break; }
  }
  if(target) break;
}
console.log('file:', target);
if(target){
  const lines=fs.readFileSync(target,'utf8').split('\n').filter(Boolean);
  let shown=0;
  for(const l of lines){
    let o; try{o=JSON.parse(l)}catch{continue}
    if(o.type!=='message'||!o.message) continue;
    for(const c of (o.message.content||[])){
      if(c.type==='toolCall' && shown<2){ console.log('KEYS:', Object.keys(c).join(','), '| name=', c.name, '| id=', (c.id||'').slice(0,8)); shown++; }
      if((c.type==='tool_use') && shown<4){ console.log('TOOL_USE KEYS:', Object.keys(c).join(',')); shown++; }
    }
  }
}
"

